script:
// Client Script for Sales Order
frappe.ui.form.on('Sales Order', {
    refresh: function(frm) {
        if (frm.doc.workflow_state === "Pending Payment Entry" && frappe.user.has_role("Accounts Manager")) {
            frm.add_custom_button(__('Check Payment Status'), function() {
                check_payment_status(frm);
            }).addClass('btn-secondary');
        }
    }
});

function check_payment_status(frm) {
    if (!frm.doc.name) {
        frappe.show_alert({
            message: __('Sales Order name is missing'),
            indicator: 'red'
        });
        return;
    }

    // Show loading message
    frappe.show_alert({
        message: __('Checking payment status...'),
        indicator: 'blue'
    });

    // Call the server script
    frappe.call({
        method: "check_so_payment_status",
        args: {
            sales_order_name: frm.doc.name
        },
        callback: function(r) {
            if (!r.exc && r.message) {
                let response = r.message;

                if (response.status === 'success') {
                    // Reload document to show updated fields
                    frm.reload_doc();

                    // Show success message
                    frappe.show_alert({
                        message: __(response.message),
                        indicator: 'green'
                    });

                    // Show detailed payment information
                    if (response.payment_info) {
                        let info = response.payment_info;
                        let payment_entries_html = '';

                        if (info.payment_entries && info.payment_entries.length > 0) {
                            payment_entries_html = `<p><strong>Linked Payment Entries:</strong><br>
                                ${info.payment_entries.map(pe => `<a href="/app/payment-entry/${pe}" target="_blank">${pe}</a>`).join('<br>')}</p>`;
                        } else {
                            payment_entries_html = '<p><em>No payment entries found</em></p>';
                        }

                        frappe.msgprint({
                            title: __('Payment Status Details'),
                            message: `
                                <div class="payment-status-info">
                                    <p><strong>Status:</strong> <span class="indicator ${info.status === 'Fully Paid' ? 'green' : 'orange'}">${info.status}</span></p>
                                    <p><strong>Total Allocated:</strong> ${format_currency(info.total_allocated, frm.doc.currency)}</p>
                                    <p><strong>Pending Amount:</strong> ${format_currency(info.pending_amount, frm.doc.currency)}</p>
                                    <p><strong>Grand Total:</strong> ${format_currency(info.grand_total, frm.doc.currency)}</p>
                                    ${payment_entries_html}
                                </div>
                            `,
                            indicator: info.status === 'Fully Paid' ? 'green' : 'orange'
                        });
                    }
                } else {
                    // Show error message
                    frappe.show_alert({
                        message: __(response.message || 'An error occurred'),
                        indicator: 'red'
                    });
                }
            } else {
                frappe.show_alert({
                    message: __('Error checking payment status'),
                    indicator: 'red'
                });
            }
        },
        error: function(err) {
            console.error("Error calling server script:", err);
            frappe.show_alert({
                message: __('Error: ') + (err.message || 'Unknown error'),
                indicator: 'red'
            });
        }
    });
}

// ask for user permission 

frappe.ui.form.on("Sales Order", {
    delivery_date: function(frm) {
        // if skip flag is set, clear it and stop execution
        if (frm._skip_confirm) {
            frm._skip_confirm = false;
            return;
        }

        if (frm.doc.delivery_date) {
            // format date as DD-MM-YYYY
            let dateObj = frappe.datetime.str_to_obj(frm.doc.delivery_date);
            let formattedDate = frappe.datetime.obj_to_user(dateObj);

            frappe.confirm(
                `Do you want to change all Item Delivery Dates with <b>${formattedDate}</b> ❓`,
                () => {
                    // YES → update all items
                    frm.doc.items.forEach(row => {
                        row.delivery_date = frm.doc.delivery_date;
                    });
                    frm.refresh_field("items");
                    frm._prev_delivery_date = frm.doc.delivery_date;
                },
                () => {
                    // NO → revert back to old value without triggering confirm again
                    frm._skip_confirm = true;
                    frappe.model.set_value(frm.doctype, frm.docname, "delivery_date", frm._prev_delivery_date || "");
                }
            );
        }
    },

    onload: function(frm) {
        frm._prev_delivery_date = frm.doc.delivery_date;
    }
});

// Merged Sales Order Client Script
// Combines payment calculation and advance allocation logic

// Function to get payment data from server script
function get_payment_data_from_server(frm, callback) {
    if (!frm.doc.customer) {
        console.log("No customer selected");
        callback({
            unallocated_payments: [],
            allocated_payments: [],
            summary: { total_unallocated: 0, total_allocated: 0 }
        });
        return;
    }

    console.log("Calling server script for payment data");

    frappe.call({
        method: 'get_payment_data_for_so',
        args: {
            'customer': frm.doc.customer,
            'sales_order_name': frm.doc.name || null
        },
        callback: function(response) {
            console.log("Server script response:", response);

            if (response.message && response.message.success) {
                callback(response.message);
            } else {
                console.error("Server script error:", response.message ? response.message.error : "Unknown error");
                callback({
                    unallocated_payments: [],
                    allocated_payments: [],
                    summary: { total_unallocated: 0, total_allocated: 0 },
                    error: response.message ? response.message.error : "Unknown error"
                });
            }
        },
        error: function(error) {
            console.error("Error calling server script:", error);
            callback({
                unallocated_payments: [],
                allocated_payments: [],
                summary: { total_unallocated: 0, total_allocated: 0 },
                error: "Failed to call server script"
            });
        }
    });
}

// Function to calculate total allocated from child table and update field
function calculate_advance_allocated(frm) {
    let advance_allocated = 0;
    if (frm.doc.custom_advances && frm.doc.custom_advances.length > 0) {
        frm.doc.custom_advances.forEach(function(row) {
            if (row.allocated_amount > 0) {
                advance_allocated += flt(row.allocated_amount);
            }
        });
    }

    // Set the field value for workflow condition usage
    frm.set_value('custom_total_advance_allocated', advance_allocated);

    return advance_allocated;
}

// Function to refresh fields and log final values
function refresh_and_log_values(frm) {
    console.log("Final values set:");
    console.log("- custom_unallocated_in_pe:", frm.doc.custom_unallocated_in_pe);
    console.log("- custom_total_unallocated_payment:", frm.doc.custom_total_unallocated_payment);
    console.log("- custom_total_payment_allocated:", frm.doc.custom_total_payment_allocated);
    console.log("- custom_total_advance_allocated:", frm.doc.custom_total_advance_allocated);
    console.log("- custom_pending_payment_amount:", frm.doc.custom_pending_payment_amount);
    console.log("- custom_payment_status:", frm.doc.custom_payment_status);

    frm.refresh_fields();
}

// Main calculation function using the server script
function calculate_unallocated_in_pe(frm) {
    console.log("Starting calculation of unallocated_in_pe");

    // Check if customer and rounded_total are available
    if (!frm.doc.customer || !frm.doc.rounded_total) {
        console.log("Customer or rounded_total not available, setting default values");
        frm.set_value('custom_unallocated_in_pe', 0);
        frm.set_value('custom_total_unallocated_payment', 0);
        frm.set_value('custom_total_payment_allocated', 0);
        frm.set_value('custom_total_advance_allocated', 0);
        frm.set_value('custom_pending_payment_amount', frm.doc.rounded_total || 0);
        frm.set_value('custom_payment_status', 'Unpaid');
        frm.set_value('custom_linked_payment_entries', '');
        refresh_and_log_values(frm);
        return;
    }

    // Call the server script to get all payment data
    get_payment_data_from_server(frm, function(payment_data) {
        console.log("Processing payment data:", payment_data);

        let total_unallocated = payment_data.summary.total_unallocated;
        let total_allocated = payment_data.summary.total_allocated;

        console.log("Total unallocated:", total_unallocated);
        console.log("Total allocated:", total_allocated);
        console.log("Sales Order grand total:", frm.doc.rounded_total);

        // Set field values
        frm.set_value('custom_total_unallocated_payment', total_unallocated);
        frm.set_value('custom_total_payment_allocated', total_allocated);

        // Calculate and set advance allocated amount
        let advance_allocated = calculate_advance_allocated(frm);

        // Calculate pending amount (considering both allocated payments and advance allocations)
        let total_covered = total_allocated + advance_allocated;
        let pending_amount = frm.doc.rounded_total - total_covered;
        frm.set_value('custom_pending_payment_amount', Math.max(0, pending_amount));

        // Determine payment status
        let payment_status;
        if (total_allocated >= frm.doc.rounded_total) {
            payment_status = 'Fully Paid';
        } else if (total_allocated > 0) {
            payment_status = 'Partially Paid';
        } else {
            payment_status = 'Unpaid';
        }
        // Determine payment status for custom field

        frm.set_value('custom_payment_status', payment_status);

        // Set checkbox based on unallocated amount
        // Updated condition with 15% buffer:
        let unallocated_with_buffer = total_unallocated * 1.15; // Add 15% buffer to unallocated amount
        if (unallocated_with_buffer > 0) {
            console.log("Unallocated amount (with 15% buffer) is sufficient, setting custom_unallocated_in_pe to 1");
            frm.set_value('custom_unallocated_in_pe', 1);
        } else {
            console.log("Unallocated amount (with 15% buffer) is insufficient, setting custom_unallocated_in_pe to 0");
            frm.set_value('custom_unallocated_in_pe', 0);
        }

        // Set linked payment entries display
        let all_pe_details = [];

        if (payment_data.unallocated_payments && payment_data.unallocated_payments.length > 0) {
            all_pe_details.push("=== UNALLOCATED PAYMENTS ===");
            payment_data.unallocated_payments.forEach(pe => {
                all_pe_details.push(`${pe.name} (${pe.posting_date}): Unallocated: ${format_currency(pe.unallocated_amount)}`);
            });
        }

        if (payment_data.allocated_payments && payment_data.allocated_payments.length > 0) {
            all_pe_details.push("=== ALLOCATED PAYMENTS ===");
            payment_data.allocated_payments.forEach(pe => {
                all_pe_details.push(`${pe.payment_entry} (${pe.posting_date}): Allocated: ${format_currency(pe.allocated_amount)}`);
            });
        } else if (total_allocated === 0 && !payment_data.error) {
            all_pe_details.push("=== ALLOCATED PAYMENTS ===");
            all_pe_details.push("No payments allocated to this Sales Order");
        } else if (payment_data.error) {
            all_pe_details.push("=== ERROR ===");
            all_pe_details.push("Could not fetch payment data: " + payment_data.error);
        }

        if (all_pe_details.length === 0) {
            all_pe_details.push("No payment entries found for this customer");
        }

        frm.set_value('custom_linked_payment_entries', all_pe_details.join('\n'));

        // Refresh fields and log final values
        refresh_and_log_values(frm);
    });
}

// Utility function to show payment entry details
function show_payment_entry_details(frm) {
    if (!frm.doc.customer) {
        frappe.msgprint("Please select a customer first");
        return;
    }

    get_payment_data_from_server(frm, function(payment_data) {
        if (payment_data.error) {
            frappe.msgprint({
                title: 'Error',
                message: 'Could not load payment entry details: ' + payment_data.error,
                indicator: 'red'
            });
            return;
        }

        let dialog_content = `
            <div class="alert alert-info">
                <strong>Payment Summary for ${frm.doc.customer}</strong><br>
                Total Unallocated: ${format_currency(payment_data.summary.total_unallocated)}<br>
                Total Allocated to this SO: ${format_currency(payment_data.summary.total_allocated)}
            </div>
        `;

        // Add unallocated payments table
        if (payment_data.unallocated_payments && payment_data.unallocated_payments.length > 0) {
            dialog_content += `
                <h4>Unallocated Payment Entries</h4>
                <table class="table table-bordered">
                    <thead>
                        <tr>
                            <th>Payment Entry</th>
                            <th>Date</th>
                            <th>Paid Amount</th>
                            <th>Unallocated Amount</th>
                        </tr>
                    </thead>
                    <tbody>
            `;

            payment_data.unallocated_payments.forEach(function(pe) {
                dialog_content += `
                    <tr>
                        <td><a href="/app/payment-entry/${pe.name}" target="_blank">${pe.name}</a></td>
                        <td>${pe.posting_date}</td>
                        <td>${format_currency(pe.paid_amount)}</td>
                        <td>${format_currency(pe.unallocated_amount)}</td>
                    </tr>
                `;
            });

            dialog_content += '</tbody></table>';
        }

        // Add allocated payments table
        if (payment_data.allocated_payments && payment_data.allocated_payments.length > 0) {
            dialog_content += `
                <h4>Allocated Payment Entries (for this SO)</h4>
                <table class="table table-bordered">
                    <thead>
                        <tr>
                            <th>Payment Entry</th>
                            <th>Date</th>
                            <th>Total Paid</th>
                            <th>Allocated to this SO</th>
                        </tr>
                    </thead>
                    <tbody>
            `;

            payment_data.allocated_payments.forEach(function(pe) {
                dialog_content += `
                    <tr>
                        <td><a href="/app/payment-entry/${pe.payment_entry}" target="_blank">${pe.payment_entry}</a></td>
                        <td>${pe.posting_date}</td>
                        <td>${format_currency(pe.paid_amount)}</td>
                        <td>${format_currency(pe.allocated_amount)}</td>
                    </tr>
                `;
            });

            dialog_content += '</tbody></table>';
        }

        if (!payment_data.unallocated_payments.length && !payment_data.allocated_payments.length) {
            dialog_content += '<div class="alert alert-warning">No payment entries found for this customer</div>';
        }

        let d = new frappe.ui.Dialog({
            title: 'Payment Entry Details for ' + frm.doc.customer,
            fields: [{
                fieldtype: 'HTML',
                fieldname: 'payment_details',
                options: dialog_content
            }],
            size: 'large'
        });
        d.show();
    });
}

// Function to fetch and add advances
function get_advances_for_sales_order(frm) {
    if (!frm.doc.customer) {
        frappe.msgprint(__('Please select a customer first'));
        return;
    }

    frappe.call({
        method: "get_sales_order_advances",
        args: { sales_order: frm.doc.name },
        callback: function(r) {
            if (r.message && r.message.length > 0) {
                frm.clear_table("custom_advances");

                r.message.forEach(function(advance) {
                    let row = frm.add_child("custom_advances");
                    row.reference_type = advance.reference_type;
                    row.reference_name = advance.reference_name;
                    row.remarks = advance.remarks;
                    row.advance_amount = advance.advance_amount;
                    row.allocated_amount = 0;
                    row.exchange_rate = advance.exchange_rate || 1;
                });

                frm.refresh_field("custom_advances");
                frappe.msgprint(__('Advances fetched successfully. Please set allocation amounts.'));
            } else {
                frappe.msgprint(__('No unallocated advances found for this customer'));
            }
        }
    });
}

// Function to validate advance allocations
function validate_advance_allocations(frm) {
    if (!frm.doc.custom_advances || frm.doc.custom_advances.length === 0) {
        return; // No advances to validate
    }

    let total_allocated = 0;
    let has_allocation = false;

    // Calculate total and check for allocations
    frm.doc.custom_advances.forEach(function(row) {
        if (row.allocated_amount > 0) {
            has_allocation = true;
            total_allocated += flt(row.allocated_amount);

            // Individual validations
            if (row.allocated_amount > row.advance_amount) {
                frappe.throw(__('Row {0}: Allocated amount ({1}) cannot exceed advance amount ({2})', 
                    [row.idx, row.allocated_amount, row.advance_amount]));
            }

            if (row.allocated_amount > frm.doc.rounded_total) {
                frappe.throw(__('Row {0}: Allocated amount ({1}) cannot exceed Sales Order total ({2})', 
                    [row.idx, row.allocated_amount, frm.doc.rounded_total]));
            }
        }
    });

    // Check total allocation
    if (total_allocated > frm.doc.rounded_total) {
        frappe.throw(__('Total allocated amount ({0}) cannot exceed Sales Order grand total ({1})', 
            [total_allocated, frm.doc.rounded_total]));
    }
}

// Check if Process Payment Complete should be available  
function should_show_process_payment_complete(frm) {
    if (frm.doc.workflow_state !== "Pending Payment Entry") {
        return false;
    }

    // Use the field value that gets set by calculate_advance_allocated()
    let advance_allocated = frm.doc.custom_total_advance_allocated || 0;

    // Show button when: rounded_total >= allocated > 0 (partially or fully paid)
    return advance_allocated > 0 && advance_allocated <= Math.round(frm.doc.rounded_total);
}

// Form event handlers with debouncing to prevent multiple calls
let calculation_timeout;

function debounced_calculate(frm) {
    if (calculation_timeout) {
        clearTimeout(calculation_timeout);
    }
    calculation_timeout = setTimeout(() => {
        calculate_unallocated_in_pe(frm);
    }, 300); // 300ms delay
}
let last_workflow_action = null;

frappe.ui.form.on('Sales Order', {
    refresh: function(frm) {
        console.log("Sales Order form refreshed");

        // Add custom buttons
        if (!frm.is_new()) {
            // Payment-related buttons
            frm.add_custom_button(__('Show Payment Details'), function() {
                show_payment_entry_details(frm);
            }, __('Actions'));

            // Show Recalculate Payments button ONLY in Draft state
            if (frm.doc.docstatus === 0) {  // 0 = Draft, 1 = Submitted, 2 = Cancelled
                frm.add_custom_button(__('Recalculate Payments'), function() {
                    calculate_unallocated_in_pe(frm);
                    frappe.show_alert({
                        message: 'Payment calculation completed',
                        indicator: 'green'
                    });
                }, __('Actions'));
            }

            // Advances button - only in Pending Payment Entry state
            if (frm.doc.workflow_state ==="Pending Payment Entry") {
                frm.add_custom_button(__('Get Advances'), function() {
                    get_advances_for_sales_order(frm);
                }, __("Actions"));
            }
        }

        // Auto-calculate payments on refresh
        // debounced_calculate(frm);
    },

    customer: function(frm) {
        console.log("Customer changed to:", frm.doc.customer);
        debounced_calculate(frm);
    },

    rounded_total: function(frm) {
        console.log("Grand total changed to:", frm.doc.rounded_total);
        debounced_calculate(frm);
    },

    before_save: function(frm) {
        console.log("Before save - ensuring payment calculation is complete");
        // Ensure calculation is complete before saving
        if (calculation_timeout) {
            clearTimeout(calculation_timeout);
        }
        calculate_unallocated_in_pe(frm);
    },
    before_workflow_action: function(frm) {
        console.log("Before workflow action: " + frm.selected_workflow_action);

        // Save it so we can use later
        last_workflow_action = frm.selected_workflow_action;

        if (frm.selected_workflow_action === "Process Payment Complete") {
            validate_advance_allocations(frm);
            calculate_unallocated_in_pe(frm);

            frappe.show_alert({
                message: 'Payments validated before completing workflow action',
                indicator: 'orange'
            });
        }
    },
    after_workflow_action: function(frm) {
        console.log("After workflow action: " + last_workflow_action);

        if (last_workflow_action === "Process Payment Complete") {
            // Add delay here
            setTimeout(() => {
                console.log("⏳ Delay finished, running recalculation...");

                validate_advance_allocations(frm);
                calculate_unallocated_in_pe(frm);

                frappe.after_ajax(() => {
                    frm.reload_doc().then(() => {
                        console.log("Recalculating after doc refresh");
                    });
                });

            }, 1000); // 1000ms = 1 second
        }

        // Reset
        last_workflow_action = null;
    }
});

// Child table events for custom_advances
frappe.ui.form.on('Custom Advances', {
    allocated_amount: function(frm, cdt, cdn) {
        // Recalculate when allocation changes
        console.log("Advance allocation changed");
        debounced_calculate(frm);
    },

    custom_advances_remove: function(frm) {
        // Recalculate when row is removed
        console.log("Advance row removed");
        debounced_calculate(frm);
    }
});

frappe.views.ListView = class ListView extends frappe.views.ListView {
    // Override skeleton to inject extra details row
    get_list_row_html_skeleton(left = "", right = "", details = "") {
        if (this.doctype === "Payment Entry") {
            if (details === null) { details = "" };
            return `
                <div class="list-row-container" tabindex="1">
                    <div class="level list-row">
                        <div class="level-left ellipsis">
                            ${left}
                        </div>
                        <div class="level-right text-muted ellipsis">
                            ${right}
                        </div>
                    </div>
                    <div class="list-row-details">
                        <div class="mobile-details">
                            ${details}
                        </div>
                    </div>
                </div>
            `;
        }
        // Return default for other doctypes
        return super.get_list_row_html_skeleton(left, right, details);
    }

    // Pass document data to skeleton
    get_list_row_html(doc) {
        const detailsContent = this.get_mobile_details(doc);
        return this.get_list_row_html_skeleton(
            this.get_left_html(doc),
            this.get_right_html(doc),
            detailsContent
        );
    }

    // Custom details for Payment Entry
    get_mobile_details(doc) {
        if (this.doctype === "Payment Entry") {
            const details = [];
            // Party Name
            if (doc.party_name) {
                details.push(`<div class="detail-item"><span class="detail-label">Party:</span><span class="detail-value">${doc.party_name}</span></div>`);
            }
            // Paid Amount
            if (doc.paid_amount) {
                details.push(`<div class="detail-item"><span class="detail-label">Paid Amount:</span><span class="detail-value">${format_currency(doc.paid_amount, doc.currency)}</span></div>`);
            }
            // Posting Date
            if (doc.posting_date) {
                details.push(`<div class="detail-item"><span class="detail-label">Posting Date:</span><span class="detail-value">${frappe.format(doc.posting_date, {fieldtype: "Date"})}</span></div>`);
            }
            return details.join('');
        }
        return '';
    }
}

// Improved CSS with proper alignment
document.querySelector('style').textContent +=
`
