async function validate_e_invoice_before_submit(frm) {
    return new Promise(async (resolve, reject) => {
        try {
            // Get GST Settings first
            const gst_settings = await frappe.db.get_single('GST Settings');

            if (!gst_settings.enable_e_invoice) {
                resolve(); // E-invoice not enabled, proceed normally
                return;
            }

            // Check date applicability
            let e_invoice_applicable_from = gst_settings.e_invoice_applicable_from;

            if (gst_settings.apply_e_invoice_only_for_selected_companies) {
                const company_setting = gst_settings.e_invoice_applicable_companies?.find(
                    row => row.company === frm.doc.company
                );

                if (!company_setting) {
                    resolve(); // Not applicable for this company
                    return;
                }

                e_invoice_applicable_from = company_setting.applicable_from;
            }

            if (!e_invoice_applicable_from) {
                resolve(); // No applicable date set
                return;
            }

            // Check if posting date is valid
            if (frappe.datetime.get_diff(frm.doc.posting_date, e_invoice_applicable_from) < 0) {
                resolve(); // Date not applicable yet
                return;
            }

            // Now validate e-invoice requirements
            const validation_result = validate_e_invoice_requirements(frm);

            if (!validation_result.is_applicable) {
                // Show validation errors
                const error_html = validation_result.errors.map(err => `• ${err}`).join('<br>');

                frappe.msgprint({
                    title: __('E-Invoice Validation Failed'),
                    message: `This invoice cannot generate e-Invoice due to following reasons:<br><br>${error_html}<br><br>Do you want to proceed anyway?`,
                    indicator: 'red',
                    primary_action: {
                        label: __('Proceed Anyway'),
                        action: () => resolve()
                    },
                    secondary_action: {
                        label: __('Fix Issues'),
                        action: () => reject('User chose to fix issues')
                    }
                });
            } else {
                // Show success message
                const message = gst_settings.auto_generate_e_invoice 
                    ? 'E-Invoice will be automatically generated after submission.'
                    : 'This invoice is eligible for e-Invoice generation. You can generate it manually after submission.';

                frappe.show_alert({
                    message: __(message),
                    indicator: gst_settings.auto_generate_e_invoice ? 'green' : 'blue'
                });

                resolve();
            }

        } catch (error) {
            console.error('Error in e-invoice validation:', error);
            resolve(); // Don't block submission due to validation errors
        }
    });
}

function validate_e_invoice_requirements(frm) {
    const errors = [];
    let is_applicable = true;

    // Check Company GSTIN
    if (!frm.doc.company_gstin) {
        is_applicable = false;
        errors.push('Company GSTIN is not set. Ensure it\'s set in Company Address.');
    }

    // Check Company GSTIN vs Billing Address GSTIN
    if (frm.doc.company_gstin && frm.doc.billing_address_gstin && 
        frm.doc.company_gstin === frm.doc.billing_address_gstin) {
        is_applicable = false;
        errors.push('Company GSTIN and Billing Address GSTIN cannot be same.');
    }

    // Check Billing Address GSTIN for domestic transactions
    if (frm.doc.place_of_supply !== '96-Other Countries' && !frm.doc.billing_address_gstin) {
        is_applicable = false;
        errors.push('Billing Address GSTIN is required for B2B categorization.');
    }

    // Check if at least one item is taxable
    const has_taxable_items = frm.doc.items.some(item => 
        ['Taxable', 'Zero-Rated'].includes(item.gst_treatment)
    );

    if (!has_taxable_items) {
        is_applicable = false;
        errors.push('All items are either Nil-Rated/Exempted/Non-GST. At least one item must be taxable or the transaction should be categorised as export.');
    }

    // Validate invoice number format
    const invoice_name = frm.doc.name;
    const valid_pattern = /^[A-Z0-9/-]+$/;

    if (!valid_pattern.test(invoice_name)) {
        is_applicable = false;
        errors.push('Invoice number contains invalid characters. Only alphanumeric, hyphen, and forward slash are allowed.');
    }

    return {
        is_applicable,
        errors
    };
}

