function get_invoice_items_for_partner(frm, from_date, to_date) {
    if (!frm.doc.sales_partner) {
        frappe.msgprint(__('Please select a Sales Partner first'));
        return;
    }

    // ✅ Ensure proper conversion to system format (YYYY-MM-DD)
    from_date = frappe.datetime.obj_to_str(frappe.datetime.str_to_obj(from_date));
    to_date = frappe.datetime.obj_to_str(frappe.datetime.str_to_obj(to_date));

    // Debug: Show the dates being sent
    console.log('Sending dates - From:', from_date, 'To:', to_date);
    frappe.show_alert({
        message: __('Fetching invoices from {0} to {1}', [from_date, to_date]),
        indicator: 'blue'
    });

    // Check for date range overlap and handle accordingly
    let should_clear_table = false;
    let existing_invoices = [];

    if (frm.doc.from_date && frm.doc.to_date && frm.doc.items && frm.doc.items.length > 0) {
        // Check if new date range overlaps with existing date range
        let existing_from = frappe.datetime.str_to_obj(frm.doc.from_date);
        let existing_to = frappe.datetime.str_to_obj(frm.doc.to_date);
        let new_from = frappe.datetime.str_to_obj(from_date);
        let new_to = frappe.datetime.str_to_obj(to_date);

        // Check for overlap: new range overlaps if new_from <= existing_to AND new_to >= existing_from
        if (new_from <= existing_to && new_to >= existing_from) {
            should_clear_table = true;
            frappe.show_alert({
                message: __('Date ranges overlap. Clearing existing items and fetching fresh data...'),
                indicator: 'orange'
            });
        } else {
            // No overlap, collect existing invoices to avoid duplicates
            frm.doc.items.forEach(function(item) {
                if (item.sales_invoice && existing_invoices.indexOf(item.sales_invoice) === -1) {
                    existing_invoices.push(item.sales_invoice);
                }
            });
        }
    }

    frappe.call({
        method: "get_sales_partner_invoice_items",
        args: { 
            sales_partner: frm.doc.sales_partner,
            from_date: from_date,
            to_date: to_date,
            existing_invoices: should_clear_table ? [] : existing_invoices,
            clear_existing: should_clear_table
        },
        callback: function(r) {
            if (r.message && r.message.length > 0) {
                // Clear table if there's overlap
                if (should_clear_table) {
                    frm.clear_table("items");
                }

                // Update date fields to reflect the combined range
                let final_from_date = from_date;
                let final_to_date = to_date;

                if (!should_clear_table && frm.doc.from_date && frm.doc.to_date) {
                    // Extend the date range to include both old and new dates
                    final_from_date = frappe.datetime.str_to_obj(from_date) < frappe.datetime.str_to_obj(frm.doc.from_date) 
                        ? from_date : frm.doc.from_date;
                    final_to_date = frappe.datetime.str_to_obj(to_date) > frappe.datetime.str_to_obj(frm.doc.to_date) 
                        ? to_date : frm.doc.to_date;
                }

                frm.set_value('from_date', final_from_date);
                frm.set_value('to_date', final_to_date);

                // Add new items to the table
                r.message.forEach(function(item_data) {
                    let row = frm.add_child("items");

                    // Invoice details
                    row.sales_invoice = item_data.sales_invoice;
                    row.customer = item_data.customer;
                    row.posting_date = item_data.posting_date;

                    // Item details
                    row.item_code = item_data.item_code;
                    row.item_name = item_data.item_name;
                    row.brand = item_data.brand;
                    row.uom = item_data.uom;
                    row.rate = item_data.rate;
                    row.qty = item_data.qty;
                    row.discount_percentage = item_data.discount_percentage;
                    row.discount_amount = item_data.discount_amount;
                    row.total_discount_amount = item_data.total_discount_amount;
                    row.net_rate = item_data.net_rate;
                    row.net_amount = item_data.net_amount;

                    // Commission details
                    row.status = item_data.status;
                    row.commission_rate = item_data.commission_rate;
                    row.commission_amount = item_data.commission_amount;
                });

                frm.refresh_field("items");

                let message = should_clear_table 
                    ? __('Table cleared and invoice items fetched successfully. Please set commission rates.')
                    : __('New invoice items added successfully. Please set commission rates.');

                frappe.msgprint(message);
            } else {
                if (should_clear_table) {
                    frm.set_value('from_date', from_date);
                    frm.set_value('to_date', to_date);
                }
                frappe.msgprint(__('No new invoice items found for the selected criteria'));
            }
        }
    });
}

