function add_workflow_functionality(frm) {
    // Handle Request Approval action
    if (frm.doc.workflow_state === 'Draft' && frm.doc.docstatus === 0) {
        // Request Approval functionality will be handled by workflow
        // But we need to update item statuses when state changes to Pending Approval
    }

