    if (frm.doc.workflow_state === 'Pending Approval') {
        // Override the approve action to check if at least one item is Approved or Requested
        frm.page.btn_primary.off('click').on('click', function() {
            if (validate_approval_action(frm)) {
                // Update any Requested items to Approved before final approval
                update_requested_to_approved(frm);
                frm.save();
            }
        });
    }
