function validate_approval_action(frm) {
    if (!frm.doc.items || frm.doc.items.length === 0) {
        frappe.msgprint(__('No items found to approve'));
        return false;
    }

    let has_approved_or_requested = frm.doc.items.some(item => 
        item.status === 'Approved' || item.status === 'Requested'
    );

    if (!has_approved_or_requested) {
        frappe.msgprint(__('At least one item must be Approved or in Requested status to proceed with approval'));
        return false;
    }

    return true;
}

function update_requested_to_approved(frm) {
    // Convert all Requested items to Approved
    frm.doc.items.forEach(function(item) {
        if (item.status === 'Requested') {
            item.status = 'Approved';
        }
    });
    frm.refresh_field('items');
}

