        row.commission_amount = (row.net_amount * row.commission_rate) / 100;
        frm.refresh_field('items');
        calculate_total_commission(frm);
    }
}

function handle_status_change(frm, cdt, cdn) {
    let row = locals[cdt][cdn];

    if (row.status === 'Rejected') {
        // Log the rejection
        log_commission_change(frm, cdt, cdn, 'rejected');

        // Set commission to 0
        row.commission_rate = 0;
        row.commission_amount = 0;
        frm.refresh_field('items');
        calculate_total_commission(frm);
    }
}

function log_commission_change(frm, cdt, cdn, change_type) {
    if (frm.doc.workflow_state !== 'Pending Approval') return;

    let row = locals[cdt][cdn];
    let current_log = frm.doc.log || '';
    let timestamp = frappe.datetime.now_datetime();
    let log_entry = '';

    if (change_type === 'rejected') {
        log_entry = `[${timestamp}] Item: ${row.item_code} (${row.item_name}) - Status changed to REJECTED. Previous commission rate: ${row.commission_rate}%\n`;
    } else if (change_type === 'commission_rate') {
        log_entry = `[${timestamp}] Item: ${row.item_code} (${row.item_name}) - Commission rate changed to: ${row.commission_rate}%\n`;
    }

    if (log_entry) {
        frm.set_value('log', current_log + log_entry);
    }
}

function calculate_total_commission(frm) {
    let total = 0;

    if (frm.doc.items) {
        frm.doc.items.forEach(item => {
            if (item.commission_amount && item.status !== 'Rejected') {
                total += item.commission_amount;
            }
        });
    }

    frm.set_value('total_commission_amount', total);
}

