function generate_next_account_number(frm) {
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Account',
            fields: ['account_number'],
            filters: { account_number: ['like', 'SSWAL%'] },
            order_by: 'CAST(SUBSTRING(account_number, 6) AS UNSIGNED) desc',
            limit_page_length: 1
        },
        callback: function(r) {
            if (!frm.doc.account_number) {
                let prefix = "SSWAL";
                let next_number = "000001";

                if (r.message && r.message.length > 0) {
                    let last_code = r.message[0].account_number;
                    if (last_code && last_code.startsWith(prefix)) {
                        let num_part = last_code.slice(prefix.length);
                        let next_num = (parseInt(num_part) + 1).toString().padStart(num_part.length, '0');
                        next_number = next_num;
                    }
                }

                frm.set_value('account_number', prefix+'-' + next_number);
            }
        }
    });
}

