function validate_hsn_codes(frm) {
    if (!frm.doc.items || frm.doc.items.length === 0) {
        return;
    }

    // Collect all HSN codes from items
    let hsn_codes = [];
    frm.doc.items.forEach(item => {
        if (item.gst_hsn_code) {
            hsn_codes.push(item.gst_hsn_code);
        }
    });

    if (hsn_codes.length === 0) {
        return;
    }

    // Check HSN codes against your custom HSN Doctype
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'HSN',
            filters: {
                'hsn_code': ['in', hsn_codes]
            },
            fields: ['hsn_code', 'description']
        },
        callback: function(r) {
            if (r.message) {
                let valid_hsn_codes = r.message.map(hsn => hsn.hsn_code);
                let invalid_items = [];

                // Find items with invalid HSN codes
                frm.doc.items.forEach(item => {
                    if (item.gst_hsn_code && !valid_hsn_codes.includes(item.gst_hsn_code)) {
                        invalid_items.push({
                            item_code: item.item_code,
                            item_name: item.item_name,
                            hsn_code: item.gst_hsn_code,
                            row: item.idx
                        });
                    }
                });

                // Display message if invalid items found
                if (invalid_items.length > 0) {
                    let message = '<b>Invalid HSN Codes Found:</b><br><br>';
                    message += '<table class="table table-bordered" style="margin-top: 10px;">';
                    message += '<thead><tr><th>Row</th><th>Item Code</th><th>Item Name</th><th>Invalid HSN Code</th></tr></thead>';
                    message += '<tbody>';

                    invalid_items.forEach(item => {
                        message += `<tr>
                            <td>${item.row}</td>
                            <td>${item.item_code}</td>
                            <td>${item.item_name || ''}</td>
                            <td><span style="color: red;">${item.hsn_code}</span></td>
                        </tr>`;
                    });

                    message += '</tbody></table>';

                    frappe.msgprint({
                        title: __('HSN Code Validation'),
                        message: message,
                        indicator: 'red'
                    });
                }
            }
        }
    });
}

function validate_hsn_codes_before_save(frm, resolve, reject) {
    if (!frm.doc.items || frm.doc.items.length === 0) {
        resolve();
        return;
    }

    // Collect all HSN codes from items
    let hsn_codes = [];
    frm.doc.items.forEach(item => {
        if (item.gst_hsn_code) {
            hsn_codes.push(item.gst_hsn_code);
        }
    });

    if (hsn_codes.length === 0) {
        resolve();
        return;
    }

    // Check HSN codes against your custom HSN Doctype
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'HSN',
            filters: {
                'hsn_code': ['in', hsn_codes]
            },
            fields: ['hsn_code', 'description']
        },
        callback: function(r) {
            if (r.message) {
                let valid_hsn_codes = r.message.map(hsn => hsn.hsn_code);
                let invalid_items = [];

                // Find items with invalid HSN codes
                frm.doc.items.forEach(item => {
                    if (item.gst_hsn_code && !valid_hsn_codes.includes(item.gst_hsn_code)) {
                        invalid_items.push({
                            item_code: item.item_code,
                            item_name: item.item_name,
                            hsn_code: item.gst_hsn_code,
                            row: item.idx
                        });
                    }
                });

                // If invalid items found, show confirmation dialog
                if (invalid_items.length > 0) {
                    let message = '<b>The following items have invalid HSN codes:</b><br><br>';
                    message += '<table class="table table-bordered" style="margin-top: 10px;">';
                    message += '<thead><tr><th>Row</th><th>Item Code</th><th>Item Name</th><th>Invalid HSN Code</th></tr></thead>';
                    message += '<tbody>';

                    invalid_items.forEach(item => {
                        message += `<tr>
                            <td>${item.row}</td>
                            <td>${item.item_code}</td>
                            <td>${item.item_name || ''}</td>
                            <td><span style="color: red;">${item.hsn_code}</span></td>
                        </tr>`;
                    });

                    message += '</tbody></table>';
                    message += '<br><b>Are you sure you want to save?</b>';

                    frappe.confirm(
                        message,
                        () => {
                            // User clicked Yes
                            resolve();
                        },
                        () => {
                            // User clicked No
                            frappe.throw(__('Save cancelled due to invalid HSN codes'));
                            reject();
                        }
                    );
                } else {
                    // No invalid items, proceed with save
                    resolve();
                }
            } else {
                resolve();
            }
        },
        error: function() {
            resolve(); // In case of error, allow save
        }
    });
}

