// Helper function to render dialog with bundles and hierarchy
function render_alternative_dialog(items, bundle_items, base_item) {
    let html = `
        <div style="max-height:400px; overflow-y:auto;">
        <table class="table table-bordered table-hover table-sm align-middle">
            <thead class="table-light">
                <tr>
                    <th>Item</th>
                    <th>Description</th>
                    <th>Price</th>
                    <th>UOM</th>
                </tr>
            </thead>
            <tbody>
    `;

    items.forEach(item => {
        const link = `/app/item/${item.name}`;
        const img = item.image
            ? `<img src="${item.image}" style="height:40px;width:40px;object-fit:cover;border-radius:4px;margin-right:8px;">`
            : '';

        // Check if this item is a bundle
        const components = bundle_items.filter(b => b.parent === item.name);

        // Format price with currency
        let price_display = '-';
        if (item.price && item.price > 0) {
            const currency = item.currency || 'INR';
            price_display = `${format_currency(item.price, currency)}`;
            if (item.price_list) {
                price_display += `<br><small class="text-muted">${item.price_list}</small>`;
            }
        }

        html += `
            <tr>
                <td>
                    <div style="display:flex;align-items:center;">
                        ${img}
                        <div>
                            <a href="${link}" target="_blank" style="font-weight:600;">
                                ${item.name}
                            </a><br>
                            <small>${item.item_name || ''}</small>
                        </div>
                    </div>
                </td>
                <td>${item.description || ''}</td>
                <td>${price_display}</td>
                <td>${item.stock_uom || ''}</td>
            </tr>
        `;

        // Add hierarchy rows for product bundle components
        if (components.length) {
            components.forEach(c => {
                html += `
                    <tr style="background:#f9f9f9;">
                        <td style="padding-left:50px;">
                            ↳ <a href="/app/item/${c.item_code}" target="_blank">${c.item_code}</a>
                        </td>
                        <td colspan="2">Qty: ${c.qty}</td>
                        <td></td>
                    </tr>
                `;
            });
        }
    });

    html += `</tbody></table></div>`;

    // Create and show dialog
    let d = new frappe.ui.Dialog({
        title: __("Item Alternatives for ") + base_item,
        size: "large",
        primary_action_label: __("Close"),
        primary_action() {
            d.hide();
        }
    });

    d.$body.html(html);
    d.show();
}

