var brandDiscounts = {};
var isBrandDiscountTriggered = false;
var manuallySetItemDiscounts = [];
var explicitZeroDiscounts = {};

// NEW: Track original brand discount values and manual changes
var originalBrandDiscounts = {};
var manualBrandDiscountChanges = {};
var brandDiscountsApplied = false;

// Utility function to safely convert values and prevent NaN
function safeNumber(value, defaultValue = 0) {
    if (value === null || value === undefined || isNaN(value) || !isFinite(value)) {
        return defaultValue;
    }
    return parseFloat(value) || defaultValue;
}

// Utility function to safely format numbers
function safeFormat(value, decimals = 2) {
    const num = safeNumber(value);
    return num.toFixed(decimals);
}

// Add function to track manual item discount changes
function trackManualItemDiscount(itemName, brand, oldDiscount, newDiscount) {
    // Remove existing entry for this item
    manuallySetItemDiscounts = manuallySetItemDiscounts.filter(item => item.name !== itemName);

    // Add new entry if discount was manually changed
    if (newDiscount !== oldDiscount) {
        manuallySetItemDiscounts.push({
            name: itemName,
            brand: brand,
            old_discount: oldDiscount,
            new_discount: newDiscount
        });
    }
}

// Add function to clear manual tracking
function clearManualItemDiscounts() {
    manuallySetItemDiscounts = [];
}

// NEW: Function to store original brand discount values
function storeOriginalBrandDiscounts(frm) {
    originalBrandDiscounts = {};
    (frm.doc.custom_dicount_table || []).forEach(row => {
        if (row.brand) {
            originalBrandDiscounts[row.brand] = safeNumber(row.manual_discount);
        }
    });
}

// NEW: Function to validate brand discount consistency with individual items
function validateBrandDiscountItemConsistency(frm) {
    return new Promise((resolve, reject) => {
        let inconsistentItems = [];
        let brandDiscountMap = {};

        // Build map of brand discounts where average equals manual (no override)
        (frm.doc.custom_dicount_table || []).forEach(row => {
            if (row.brand) {
                const avgDiscount = safeNumber(row.custom_average_discount);
                const manualDiscount = safeNumber(row.manual_discount);

                // Check if average equals manual (allowing small rounding differences)
                if (Math.abs(avgDiscount - manualDiscount) <= 0.01) {
                    brandDiscountMap[row.brand] = {
                        expected_discount: manualDiscount,
                        brand_table_discount: manualDiscount
                    };
                }
            }
        });

        // Check each item against expected brand discount
        (frm.doc.items || []).forEach(item => {
            if (item.brand && brandDiscountMap[item.brand]) {
                const expectedDiscount = brandDiscountMap[item.brand].expected_discount;
                const actualDiscount = safeNumber(item.discount_percentage);

                // Allow small rounding differences (0.01%)
                if (Math.abs(expectedDiscount - actualDiscount) > 0.01) {
                    inconsistentItems.push({
                        item_code: item.item_code,
                        item_name: item.item_name || item.item_code,
                        brand: item.brand,
                        expected_discount: expectedDiscount,
                        actual_discount: actualDiscount,
                        difference: Math.abs(expectedDiscount - actualDiscount)
                    });
                }
            }
        });

        if (inconsistentItems.length > 0) {
            // Create detailed error message
            let message = `<div style='max-height: 400px; overflow-y: auto;'>`;
            message += `<strong>Brand Discount Consistency Error!</strong><br><br>`;
            message += `The following items have discount percentages that don't match their brand's standard discount:<br><br>`;

            message += `<table style='width: 100%; border-collapse: collapse; font-size: 12px;'>`;
            message += `<tr style='background: #f8f9fa; font-weight: bold;'>`;
            message += `<td style='padding: 8px; border: 1px solid #ddd;'>Item Code</td>`;
            message += `<td style='padding: 8px; border: 1px solid #ddd;'>Brand</td>`;
            message += `<td style='padding: 8px; border: 1px solid #ddd;'>Expected Discount</td>`;
            message += `<td style='padding: 8px; border: 1px solid #ddd;'>Actual Discount</td>`;
            message += `<td style='padding: 8px; border: 1px solid #ddd;'>Difference</td>`;
            message += `</tr>`;

            inconsistentItems.forEach(item => {
                message += `<tr style='background: #f8d7da;'>`;
                message += `<td style='padding: 8px; border: 1px solid #ddd;'><strong>${item.item_code}</strong></td>`;
                message += `<td style='padding: 8px; border: 1px solid #ddd;'>${item.brand}</td>`;
                message += `<td style='padding: 8px; border: 1px solid #ddd; text-align: center;'>${safeFormat(item.expected_discount, 2)}%</td>`;
                message += `<td style='padding: 8px; border: 1px solid #ddd; text-align: center;'>${safeFormat(item.actual_discount, 2)}%</td>`;
                message += `<td style='padding: 8px; border: 1px solid #ddd; text-align: center; color: red;'>${safeFormat(item.difference, 2)}%</td>`;
                message += `</tr>`;
            });

            message += `</table></div><br>`;
            message += `<div style='background: #e7f3ff; padding: 10px; border-left: 4px solid #007bff; margin: 10px 0;'>`;
            message += `<strong>Why this matters:</strong><br>`;
            message += `When the brand's average discount equals the manual discount, it means no manual override was applied. `;
            message += `All items of that brand should have the same discount percentage as specified in the brand discount table.`;
            message += `</div>`;
            message += `<strong>Recommended Actions:</strong><br>`;
            message += `• <strong>Auto-Fix Items:</strong> Update all items to match their brand discount<br>`;
            message += `• <strong>Continue Anyway:</strong> Save with inconsistent discounts (not recommended)<br>`;
            message += `• <strong>Cancel:</strong> Go back to review and fix manually`;

            // Create dialog with options
            let d = new frappe.ui.Dialog({
                title: 'Brand Discount Consistency Validation',
                fields: [
                    {
                        fieldname: 'message_html',
                        fieldtype: 'HTML',
                        options: message
                    }
                ],
                primary_action_label: 'Auto-Fix Items',
                primary_action(values) {
                    // Auto-fix all inconsistent items
                    let fixedCount = 0;

                    inconsistentItems.forEach(item => {
                        // Find the item in the form and update its discount
                        let formItem = frm.doc.items.find(i => i.item_code === item.item_code && i.brand === item.brand);
                        if (formItem) {
                            frappe.model.set_value(formItem.doctype, formItem.name, "discount_percentage", item.expected_discount);
                            fixedCount++;
                        }
                    });

                    // Refresh the form
                    frm.refresh_field("items");

                    frappe.show_alert({
                        message: `Fixed discount for ${fixedCount} items to match brand standards`,
                        indicator: 'green'
                    });

                    d.hide();

                    // Update brand averages after fixing
                    setTimeout(() => {
                        updateBrandAveragesOnly(frm);
                        resolve(); // Continue with save
                    }, 500);
                },
                secondary_action_label: 'Continue Anyway',
                secondary_action() {
                    frappe.show_alert({
                        message: 'Saving with inconsistent brand discounts',
                        indicator: 'orange'
                    });
                    d.hide();
                    resolve(); // Continue with save
                }
            });

            // Add cancel button
            d.set_secondary_action(() => {
                d.hide();
                reject(); // Cancel save
            });

            d.show();

        } else {
            // All items are consistent with their brand discounts
            resolve();
        }
    });
}

// Standalone function for manual validation (can be called from a button)
function runBrandDiscountItemConsistencyValidation(frm) {
    validateBrandDiscountItemConsistency(frm).then(() => {
        frappe.show_alert({
            message: 'All item discounts are consistent with their brand standards!',
            indicator: 'green'
        });
    }).catch(() => {
        frappe.show_alert({
            message: 'Brand discount consistency validation cancelled',
            indicator: 'orange'
        });
    });
}


// UPDATED: Enhanced before_save function with consistency validation
function enhancedBeforeSave(frm) {
    return new Promise(async (resolve, reject) => {
        try {
            cleanNaNValues(frm);

            // First check for unapplied brand discount changes
            if (hasUnappliedBrandDiscountChanges(frm)) {
                frappe.confirm(
                    "Your brand wise discount is still not applied to items. Please finalize and save brand wise discount to proceed.",
                    function() {
                        reject();
                        return false;
                    },
                    function() {
                        reject();
                        return false;
                    }
                );
                return;
            }

            // NEW: Validate brand discount and item consistency
            await validateBrandDiscountItemConsistency(frm);

            // Validate that brand discount totals match item totals
            await validateBrandDiscountTotals(frm);

            // If we reach here, everything is good
            clearManualItemDiscounts();
            resolve();

        } catch (error) {
            console.error('Validation error:', error);
            reject();
        }
    });
}

// NEW: Function to track manual brand discount changes
function trackManualBrandDiscountChange(brand, oldValue, newValue) {
    if (safeNumber(oldValue) !== safeNumber(newValue)) {
        manualBrandDiscountChanges[brand] = {
            original: safeNumber(oldValue),
            current: safeNumber(newValue)
        };
    } else {
        // Remove if values are same
        delete manualBrandDiscountChanges[brand];
    }
}

// NEW: Function to check if there are unapplied brand discount changes
function hasUnappliedBrandDiscountChanges(frm) {
    // Check if there are any manual changes that haven't been applied
    return Object.keys(manualBrandDiscountChanges).length > 0 && !brandDiscountsApplied;
}

// NEW: Function to clear brand discount tracking
function clearBrandDiscountTracking() {
    manualBrandDiscountChanges = {};
    brandDiscountsApplied = false;
}

// Add function to get items that would be overridden
function getItemsToOverride(frm) {
    let itemsToOverride = [];

    manuallySetItemDiscounts.forEach(manualItem => {
        // Find corresponding brand discount
        let brandDiscount = frm.doc.custom_dicount_table.find(row => row.brand === manualItem.brand);

        if (brandDiscount && safeNumber(brandDiscount.manual_discount) !== safeNumber(manualItem.new_discount)) {
            // Find the actual item in the form
            let item = frm.doc.items.find(i => i.name === manualItem.name);
            if (item) {
                itemsToOverride.push({
                    item_code: item.item_code,
                    brand: item.brand,
                    current_discount: manualItem.new_discount,
                    new_discount: brandDiscount.manual_discount
                });
            }
        }
    });

    return itemsToOverride;
}

// Fetch brand separately for each Pricing Rule
function getBrandFromPricingRule(pricingRuleName, discountPercentage, brandDiscounts) {
    frappe.call({
        method: "frappe.client.get",
        args: {
            doctype: "Pricing Rule",
            name: pricingRuleName
        },
        async: true,
        callback: function(response) {
            if (response.message && response.message.brands) {
                // Store discount percentage for the brand
                brandDiscounts[response.message.brands[0].brand] = safeNumber(discountPercentage);
            }
        }
    });
}

// Modified apply_brand_discounts function
function apply_brand_discounts(frm) {
    let brand_discounts = {};
    let exceeds_discount = false;

    (frm.doc.custom_dicount_table || []).forEach(row => {
        if (row.brand && row.manual_discount !== undefined) {
            const manualDiscount = safeNumber(row.manual_discount);
            const discDiscount = safeNumber(row.disc_);

            // Track if manual discount is explicitly set to zero
            if (manualDiscount === 0) {
                explicitZeroDiscounts[row.brand] = true;
            } else if (manualDiscount > 0) {
                // Remove from explicit zero tracking if set to positive value
                delete explicitZeroDiscounts[row.brand];
            }

            if (manualDiscount !== 0) {
                brand_discounts[row.brand] = manualDiscount;
            } else {
                // Use zero if explicitly set, otherwise use disc_
                brand_discounts[row.brand] = explicitZeroDiscounts[row.brand] ? 0 : discDiscount;
            }
        }
        if (safeNumber(row.manual_discount) > safeNumber(row.max_discount)) {
            exceeds_discount = true;
        }
    });

    (frm.doc.items || []).forEach(item => {
        if (item.brand && brand_discounts[item.brand] !== undefined) {
            let new_discount = brand_discounts[item.brand];
            frappe.model.set_value(item.doctype, item.name, "discount_percentage", new_discount);
        }
    });

    (frm.doc.custom_dicount_table || []).forEach(row => {
        if (row.brand && brand_discounts[row.brand] !== undefined) {
            const discountAmount = safeNumber((safeNumber(row.value) * safeNumber(row.custom_average_discount)) / 100);
            row.discount_amount = safeFormat(discountAmount);
            row.total_value = safeFormat(safeNumber(row.value) - discountAmount);
        }
    });

    cleanNaNValues(frm);
    frm.refresh_field("items");
    frm.refresh_field("custom_dicount_table");

    // NEW: Mark brand discounts as applied and clear tracking
    brandDiscountsApplied = true;
    clearBrandDiscountTracking();
    storeOriginalBrandDiscounts(frm);

    if (exceeds_discount) {
        if ("custom_requires_approval_for_discount" in frm.doc) {
            frm.set_value("custom_requires_approval_for_discount", 1);
        } else {
            console.error("Error: Field 'custom_requires_approval' not found in Sales Order Doctype!");
        }

        if (frm.doc.custom_requires_approval_for_discount) {
            frm.refresh();
        }
    }
}


// Enhanced validation function using total comparison approach
function validateBrandDiscountTotals(frm) {
    return new Promise((resolve, reject) => {
        let brand_item_totals = {};
        let brand_table_totals = {};
        let mismatched_brands = [];

        // Calculate totals from ITEMS table by brand
        (frm.doc.items || []).forEach(item => {
            if (item.brand && item.brand !== "OTHERS") {
                if (!brand_item_totals[item.brand]) {
                    brand_item_totals[item.brand] = {
                        total_value: 0,
                        total_discount_amount: 0,
                        item_count: 0
                    };
                }

                const itemValue = safeNumber(item.price_list_rate) * safeNumber(item.qty);
                const discountAmount = (itemValue * safeNumber(item.discount_percentage)) / 100;

                brand_item_totals[item.brand].total_value += itemValue;
                brand_item_totals[item.brand].total_discount_amount += discountAmount;
                brand_item_totals[item.brand].item_count += 1;
            }
        });

        // Get totals from BRAND DISCOUNT table
        (frm.doc.custom_dicount_table || []).forEach(row => {
            if (row.brand && row.brand !== "OTHERS") {
                brand_table_totals[row.brand] = {
                    table_value: safeNumber(row.value),
                    table_discount_amount: safeNumber(row.discount_amount),
                    expected_total_value: safeNumber(row.total_value)
                };
            }
        });

        // Compare totals and find mismatches
        Object.keys(brand_item_totals).forEach(brand => {
            const itemTotals = brand_item_totals[brand];
            const tableTotals = brand_table_totals[brand];

            if (tableTotals) {
                // Allow small rounding differences (0.01)
                const valueDiff = Math.abs(itemTotals.total_value - tableTotals.table_value);
                const discountDiff = Math.abs(itemTotals.total_discount_amount - tableTotals.table_discount_amount);
                const netValueDiff = Math.abs((itemTotals.total_value - itemTotals.total_discount_amount) - tableTotals.expected_total_value);

                if (valueDiff > 0.01 || discountDiff > 0.01 || netValueDiff > 0.01) {
                    mismatched_brands.push({
                        brand: brand,
                        item_count: itemTotals.item_count,
                        // Item totals
                        item_total_value: itemTotals.total_value,
                        item_discount_amount: itemTotals.total_discount_amount,
                        item_net_value: itemTotals.total_value - itemTotals.total_discount_amount,
                        // Brand table totals
                        table_total_value: tableTotals.table_value,
                        table_discount_amount: tableTotals.table_discount_amount,
                        table_net_value: tableTotals.expected_total_value,
                        // Differences
                        value_difference: valueDiff,
                        discount_difference: discountDiff,
                        net_difference: netValueDiff
                    });
                }
            } else {
                // Brand exists in items but not in brand discount table
                mismatched_brands.push({
                    brand: brand,
                    item_count: itemTotals.item_count,
                    item_total_value: itemTotals.total_value,
                    item_discount_amount: itemTotals.total_discount_amount,
                    item_net_value: itemTotals.total_value - itemTotals.total_discount_amount,
                    table_total_value: 0,
                    table_discount_amount: 0,
                    table_net_value: 0,
                    value_difference: itemTotals.total_value,
                    discount_difference: itemTotals.total_discount_amount,
                    net_difference: itemTotals.total_value - itemTotals.total_discount_amount,
                    missing_from_table: true
                });
            }
        });

        // Check for brands in table but not in items
        Object.keys(brand_table_totals).forEach(brand => {
            if (!brand_item_totals[brand] && brand_table_totals[brand].table_value > 0.01) {
                mismatched_brands.push({
                    brand: brand,
                    item_count: 0,
                    item_total_value: 0,
                    item_discount_amount: 0,
                    item_net_value: 0,
                    table_total_value: brand_table_totals[brand].table_value,
                    table_discount_amount: brand_table_totals[brand].table_discount_amount,
                    table_net_value: brand_table_totals[brand].expected_total_value,
                    value_difference: brand_table_totals[brand].table_value,
                    discount_difference: brand_table_totals[brand].table_discount_amount,
                    net_difference: brand_table_totals[brand].expected_total_value,
                    missing_from_items: true
                });
            }
        });

        if (mismatched_brands.length > 0) {
            // Create detailed comparison message
            let message = `<div style='max-height: 400px; overflow-y: auto;'>`;
            message += `<strong>Brand Discount Total Mismatch Detected!</strong><br><br>`;
            message += `The following brands have mismatched totals between items and brand discount table:<br><br>`;

            message += `<table style='width: 100%; border-collapse: collapse; font-size: 12px;'>`;
            message += `<tr style='background: #f8f9fa; font-weight: bold;'>`;
            message += `<td style='padding: 6px; border: 1px solid #ddd;'>Brand</td>`;
            message += `<td style='padding: 6px; border: 1px solid #ddd;'>Items Count</td>`;
            message += `<td style='padding: 6px; border: 1px solid #ddd;'>Item Total</td>`;
            message += `<td style='padding: 6px; border: 1px solid #ddd;'>Item Discount</td>`;
            message += `<td style='padding: 6px; border: 1px solid #ddd;'>Table Total</td>`;
            message += `<td style='padding: 6px; border: 1px solid #ddd;'>Table Discount</td>`;
            message += `<td style='padding: 6px; border: 1px solid #ddd;'>Issue</td>`;
            message += `</tr>`;

            mismatched_brands.forEach(brand => {
                let issueType = '';
                if (brand.missing_from_table) {
                    issueType = '<span style="color: red;">Missing from brand table</span>';
                } else if (brand.missing_from_items) {
                    issueType = '<span style="color: orange;">No items for this brand</span>';
                } else {
                    let issues = [];
                    if (brand.value_difference > 0.01) issues.push('Value');
                    if (brand.discount_difference > 0.01) issues.push('Discount');
                    issueType = `<span style="color: red;">Mismatch: ${issues.join(', ')}</span>`;
                }

                message += `<tr style='${brand.missing_from_table || brand.missing_from_items ? 'background: #fff3cd;' : 'background: #f8d7da;'}'>`;
                message += `<td style='padding: 6px; border: 1px solid #ddd;'><strong>${brand.brand}</strong></td>`;
                message += `<td style='padding: 6px; border: 1px solid #ddd; text-align: center;'>${brand.item_count}</td>`;
                message += `<td style='padding: 6px; border: 1px solid #ddd; text-align: right;'>${safeFormat(brand.item_total_value)}</td>`;
                message += `<td style='padding: 6px; border: 1px solid #ddd; text-align: right;'>${safeFormat(brand.item_discount_amount)}</td>`;
                message += `<td style='padding: 6px; border: 1px solid #ddd; text-align: right;'>${safeFormat(brand.table_total_value)}</td>`;
                message += `<td style='padding: 6px; border: 1px solid #ddd; text-align: right;'>${safeFormat(brand.table_discount_amount)}</td>`;
                message += `<td style='padding: 6px; border: 1px solid #ddd;'>${issueType}</td>`;
                message += `</tr>`;
            });

            message += `</table></div><br>`;
            message += `<strong>Recommended Actions:</strong><br>`;
            message += `• <strong>Refresh Brand Discounts:</strong> Update brand discount table to match current items<br>`;
            message += `• <strong>Continue Anyway:</strong> Save with current mismatched totals<br>`;
            message += `• <strong>Cancel:</strong> Go back to review and fix manually`;

            // Create dialog with options
            let d = new frappe.ui.Dialog({
                title: 'Brand Discount Total Validation',
                fields: [
                    {
                        fieldname: 'message_html',
                        fieldtype: 'HTML',
                        options: message
                    }
                ],
                primary_action_label: 'Refresh Brand Discounts',
                primary_action(values) {
                    // Trigger brand discount update to fix mismatches
                    frm.trigger("update_brand_discounts").then(() => {
                        frappe.show_alert({
                            message: `Brand discounts refreshed for ${mismatched_brands.length} brands`,
                            indicator: 'green'
                        });

                        d.hide();

                        // Re-validate after refresh
                        setTimeout(() => {
                            validateBrandDiscountTotals(frm).then(() => {
                                resolve(); // Continue with save if validation passes
                            }).catch(() => {
                                reject(); // Cancel save if still issues
                            });
                        }, 500);
                    });
                },
                secondary_action_label: 'Continue Anyway',
                secondary_action() {
                    frappe.show_alert({
                        message: 'Saving with mismatched brand totals',
                        indicator: 'orange'
                    });
                    d.hide();
                    resolve(); // Continue with save
                }
            });

            // Add cancel button
            d.set_secondary_action(() => {
                d.hide();
                reject(); // Cancel save
            });

            d.show();

        } else {
            // All totals match
            resolve();
        }
    });
}
