var brandDiscounts = {};
var isBrandDiscountTriggered = false;
var manuallySetItemDiscounts = [];
var explicitZeroDiscounts = {};

// NEW: Track original brand discount values and manual changes
var originalBrandDiscounts = {};
var manualBrandDiscountChanges = {};
var brandDiscountsApplied = false;

// Utility function to safely convert values and prevent NaN
function safeNumber(value, defaultValue = 0) {
    if (value === null || value === undefined || isNaN(value) || !isFinite(value)) {
        return defaultValue;
    }
    return parseFloat(value) || defaultValue;
}

// Utility function to safely format numbers
function safeFormat(value, decimals = 2) {
    const num = safeNumber(value);
    return num.toFixed(decimals);
}

// Add function to track manual item discount changes
function trackManualItemDiscount(itemName, brand, oldDiscount, newDiscount) {
    // Remove existing entry for this item
    manuallySetItemDiscounts = manuallySetItemDiscounts.filter(item => item.name !== itemName);
    
    // Add new entry if discount was manually changed
    if (newDiscount !== oldDiscount) {
        manuallySetItemDiscounts.push({
            name: itemName,
            brand: brand,
            old_discount: oldDiscount,
            new_discount: newDiscount
        });
    }
}

// Add function to clear manual tracking
function clearManualItemDiscounts() {
    manuallySetItemDiscounts = [];
}

// NEW: Function to store original brand discount values
function storeOriginalBrandDiscounts(frm) {
    originalBrandDiscounts = {};
    (frm.doc.custom_dicount_table || []).forEach(row => {
        if (row.brand) {
            originalBrandDiscounts[row.brand] = safeNumber(row.manual_discount);
        }
    });
}


// NEW: Function to track manual brand discount changes
function trackManualBrandDiscountChange(brand, oldValue, newValue) {
    if (safeNumber(oldValue) !== safeNumber(newValue)) {
        manualBrandDiscountChanges[brand] = {
            original: safeNumber(oldValue),
            current: safeNumber(newValue)
        };
    } else {
        // Remove if values are same
        delete manualBrandDiscountChanges[brand];
    }
}

// NEW: Function to check if there are unapplied brand discount changes
function hasUnappliedBrandDiscountChanges(frm) {
    // Check if there are any manual changes that haven't been applied
    return Object.keys(manualBrandDiscountChanges).length > 0 && !brandDiscountsApplied;
}

// NEW: Function to clear brand discount tracking
function clearBrandDiscountTracking() {
    manualBrandDiscountChanges = {};
    brandDiscountsApplied = false;
}

// Add function to get items that would be overridden
function getItemsToOverride(frm) {
    let itemsToOverride = [];
    
    manuallySetItemDiscounts.forEach(manualItem => {
        // Find corresponding brand discount
        let brandDiscount = frm.doc.custom_dicount_table.find(row => row.brand === manualItem.brand);
        
        if (brandDiscount && safeNumber(brandDiscount.manual_discount) !== safeNumber(manualItem.new_discount)) {
            // Find the actual item in the form
            let item = frm.doc.items.find(i => i.name === manualItem.name);
            if (item) {
                itemsToOverride.push({
                    item_code: item.item_code,
                    brand: item.brand,
                    current_discount: manualItem.new_discount,
                    new_discount: brandDiscount.manual_discount
                });
            }
        }
    });
    
    return itemsToOverride;
}

// Fetch brand separately for each Pricing Rule
function getBrandFromPricingRule(pricingRuleName, discountPercentage, brandDiscounts) {
    frappe.call({
        method: "frappe.client.get",
        args: {
            doctype: "Pricing Rule",
            name: pricingRuleName
        },
        async: true,
        callback: function(response) {
            if (response.message && response.message.brands) {
                // Store discount percentage for the brand
                brandDiscounts[response.message.brands[0].brand] = safeNumber(discountPercentage);
            }
        }
    });
}

// Method 3: Using batch updates with frappe.model.set_value (controlled)
function apply_brand_discounts(frm) {
    let brand_discounts = {};
    let exceeds_discount = false;

    // Build brand discounts map (same as before)
    (frm.doc.custom_dicount_table || []).forEach(row => {
        if (row.brand && row.manual_discount !== undefined) {
            const manualDiscount = safeNumber(row.manual_discount);
            const discDiscount = safeNumber(row.disc_);
            
            if (manualDiscount === 0) {
                explicitZeroDiscounts[row.brand] = true;
            } else if (manualDiscount > 0) {
                delete explicitZeroDiscounts[row.brand];
            }
            
            brand_discounts[row.brand] = manualDiscount !== 0 ? manualDiscount : 
                (explicitZeroDiscounts[row.brand] ? 0 : discDiscount);
        }
        if (safeNumber(row.manual_discount) > safeNumber(row.max_discount)) {
            exceeds_discount = true;
        }
    });

    // Disable auto-calculation temporarily
    frm.doc.__onload = frm.doc.__onload || {};
    frm.doc.__onload.ignore_validate = true;

    // Batch update items
    let updates_pending = 0;
    (frm.doc.items || []).forEach(item => {
        if (item.brand && brand_discounts[item.brand] !== undefined) {
            const new_discount = brand_discounts[item.brand];
            if (safeNumber(item.discount_percentage) !== new_discount) {
                updates_pending++;
                // Use frappe.model.set_value but batch the updates
                frappe.model.set_value(item.doctype, item.name, "discount_percentage", new_discount);
            }
        }
    });

    // Re-enable calculations and trigger once
    setTimeout(() => {
        delete frm.doc.__onload.ignore_validate;
        if (updates_pending > 0) {
            frm.calculate_taxes_and_totals();
            frm.refresh_field("items");
        }
    }, 200);

    // Update brand discount table and finish
    (frm.doc.custom_dicount_table || []).forEach(row => {
        if (row.brand && brand_discounts[row.brand] !== undefined) {
            const discountAmount = safeNumber((safeNumber(row.value) * safeNumber(row.custom_average_discount)) / 100);
            row.discount_amount = safeFormat(discountAmount);
            row.total_value = safeFormat(safeNumber(row.value) - discountAmount);
        }
    });

    cleanNaNValues(frm);
    frm.refresh_field("custom_dicount_table");

    brandDiscountsApplied = true;
    clearBrandDiscountTracking();
    storeOriginalBrandDiscounts(frm);

    if (exceeds_discount) {
        if ("custom_requires_approval_for_discount" in frm.doc) {
            frm.set_value("custom_requires_approval_for_discount", 1);
        }
        if (frm.doc.custom_requires_approval_for_discount) {
            frm.refresh();
        }
    }
}


// SOLUTION 1: Increase tolerance in validation function
// Replace your existing validateBrandDiscountTotals function with this:

function validateBrandDiscountTotals(frm) {
    return new Promise((resolve, reject) => {
        let brand_item_totals = {};
        let brand_table_totals = {};
        let mismatched_brands = [];
        
        // Calculate totals from ITEMS table by brand
        (frm.doc.items || []).forEach(item => {
            if (item.brand && item.brand !== "OTHERS") {
                if (!brand_item_totals[item.brand]) {
                    brand_item_totals[item.brand] = {
                        total_value: 0,
                        total_discount_amount: 0,
                        item_count: 0
                    };
                }
                
                const itemValue = safeNumber(item.price_list_rate) * safeNumber(item.qty);
                const discountAmount = (itemValue * safeNumber(item.discount_percentage)) / 100;
                
                brand_item_totals[item.brand].total_value += itemValue;
                brand_item_totals[item.brand].total_discount_amount += discountAmount;
                brand_item_totals[item.brand].item_count += 1;
            }
        });
        
        // Get totals from BRAND DISCOUNT table
        (frm.doc.custom_dicount_table || []).forEach(row => {
            if (row.brand && row.brand !== "OTHERS") {
                brand_table_totals[row.brand] = {
                    table_value: safeNumber(row.value),
                    table_discount_amount: safeNumber(row.discount_amount),
                    expected_total_value: safeNumber(row.total_value)
                };
            }
        });
        
        // Compare totals and find mismatches
        Object.keys(brand_item_totals).forEach(brand => {
            const itemTotals = brand_item_totals[brand];
            const tableTotals = brand_table_totals[brand];
            
            if (tableTotals) {
                // INCREASED tolerance for floating-point precision errors (from 0.01 to 0.10)
                const TOLERANCE = 0.10;
                
                const valueDiff = Math.abs(itemTotals.total_value - tableTotals.table_value);
                const discountDiff = Math.abs(itemTotals.total_discount_amount - tableTotals.table_discount_amount);
                const netValueDiff = Math.abs((itemTotals.total_value - itemTotals.total_discount_amount) - tableTotals.expected_total_value);
                
                // Only flag as mismatch if differences exceed tolerance
                if (valueDiff > TOLERANCE || discountDiff > TOLERANCE || netValueDiff > TOLERANCE) {
                    mismatched_brands.push({
                        brand: brand,
                        item_count: itemTotals.item_count,
                        // Item totals
                        item_total_value: itemTotals.total_value,
                        item_discount_amount: itemTotals.total_discount_amount,
                        item_net_value: itemTotals.total_value - itemTotals.total_discount_amount,
                        // Brand table totals
                        table_total_value: tableTotals.table_value,
                        table_discount_amount: tableTotals.table_discount_amount,
                        table_net_value: tableTotals.expected_total_value,
                        // Differences
                        value_difference: valueDiff,
                        discount_difference: discountDiff,
                        net_difference: netValueDiff
                    });
                }
            } else {
                // Brand exists in items but not in brand discount table
                mismatched_brands.push({
                    brand: brand,
                    item_count: itemTotals.item_count,
                    item_total_value: itemTotals.total_value,
                    item_discount_amount: itemTotals.total_discount_amount,
                    item_net_value: itemTotals.total_value - itemTotals.total_discount_amount,
                    table_total_value: 0,
                    table_discount_amount: 0,
                    table_net_value: 0,
                    value_difference: itemTotals.total_value,
                    discount_difference: itemTotals.total_discount_amount,
                    net_difference: itemTotals.total_value - itemTotals.total_discount_amount,
                    missing_from_table: true
                });
            }
        });
        
        // Check for brands in table but not in items
        Object.keys(brand_table_totals).forEach(brand => {
            const TOLERANCE = 0.10;
            if (!brand_item_totals[brand] && brand_table_totals[brand].table_value > TOLERANCE) {
                mismatched_brands.push({
                    brand: brand,
                    item_count: 0,
                    item_total_value: 0,
                    item_discount_amount: 0,
                    item_net_value: 0,
                    table_total_value: brand_table_totals[brand].table_value,
                    table_discount_amount: brand_table_totals[brand].table_discount_amount,
                    table_net_value: brand_table_totals[brand].expected_total_value,
                    value_difference: brand_table_totals[brand].table_value,
                    discount_difference: brand_table_totals[brand].table_discount_amount,
                    net_difference: brand_table_totals[brand].expected_total_value,
                    missing_from_items: true
                });
            }
        });
        
        if (mismatched_brands.length > 0) {
            // Create detailed comparison message
            let message = `<div style='max-height: 400px; overflow-y: auto;'>`;
            message += `<strong>Brand Discount Total Mismatch Detected!</strong><br><br>`;
            message += `The following brands have significant mismatches (>0.10) between items and brand discount table:<br><br>`;
            
            message += `<table style='width: 100%; border-collapse: collapse; font-size: 12px;'>`;
            message += `<tr style='background: #f8f9fa; font-weight: bold;'>`;
            message += `<td style='padding: 6px; border: 1px solid #ddd;'>Brand</td>`;
            message += `<td style='padding: 6px; border: 1px solid #ddd;'>Items Count</td>`;
            message += `<td style='padding: 6px; border: 1px solid #ddd;'>Item Total</td>`;
            message += `<td style='padding: 6px; border: 1px solid #ddd;'>Item Discount</td>`;
            message += `<td style='padding: 6px; border: 1px solid #ddd;'>Table Total</td>`;
            message += `<td style='padding: 6px; border: 1px solid #ddd;'>Table Discount</td>`;
            message += `<td style='padding: 6px; border: 1px solid #ddd;'>Difference</td>`;
            message += `<td style='padding: 6px; border: 1px solid #ddd;'>Issue</td>`;
            message += `</tr>`;
            
            mismatched_brands.forEach(brand => {
                let issueType = '';
                if (brand.missing_from_table) {
                    issueType = '<span style="color: red;">Missing from brand table</span>';
                } else if (brand.missing_from_items) {
                    issueType = '<span style="color: orange;">No items for this brand</span>';
                } else {
