                    if (brand.value_difference > 0.10) issues.push('Value');
                    if (brand.discount_difference > 0.10) issues.push('Discount');
                    issueType = `<span style="color: red;">Mismatch: ${issues.join(', ')}</span>`;
                }
                
                // Show the maximum difference for this brand
                const maxDiff = Math.max(brand.value_difference || 0, brand.discount_difference || 0, brand.net_difference || 0);
                
                message += `<tr style='${brand.missing_from_table || brand.missing_from_items ? 'background: #fff3cd;' : 'background: #f8d7da;'}'>`;
                message += `<td style='padding: 6px; border: 1px solid #ddd;'><strong>${brand.brand}</strong></td>`;
                message += `<td style='padding: 6px; border: 1px solid #ddd; text-align: center;'>${brand.item_count}</td>`;
                message += `<td style='padding: 6px; border: 1px solid #ddd; text-align: right;'>${safeFormat(brand.item_total_value)}</td>`;
