// NEW: Function to validate brand discount consistency with individual items
function validateBrandDiscountItemConsistency(frm) {
    return new Promise((resolve, reject) => {
        let inconsistentItems = [];
        let brandDiscountMap = {};
        
        // Build map of brand discounts where average equals manual (no override)
        (frm.doc.custom_dicount_table || []).forEach(row => {
            if (row.brand) {
                const avgDiscount = safeNumber(row.custom_average_discount);
                const manualDiscount = safeNumber(row.manual_discount);
                
                // Check if average equals manual (allowing small rounding differences)
                if (Math.abs(avgDiscount - manualDiscount) <= 0.01) {
                    brandDiscountMap[row.brand] = {
                        expected_discount: manualDiscount,
                        brand_table_discount: manualDiscount
                    };
                }
            }
        });
        
        // Check each item against expected brand discount
        (frm.doc.items || []).forEach(item => {
            if (item.brand && brandDiscountMap[item.brand]) {
                const expectedDiscount = brandDiscountMap[item.brand].expected_discount;
                const actualDiscount = safeNumber(item.discount_percentage);
                
                // Allow small rounding differences (0.01%)
                if (Math.abs(expectedDiscount - actualDiscount) > 0.01) {
                    inconsistentItems.push({
                        item_code: item.item_code,
                        item_name: item.item_name || item.item_code,
                        brand: item.brand,
                        expected_discount: expectedDiscount,
                        actual_discount: actualDiscount,
                        difference: Math.abs(expectedDiscount - actualDiscount)
                    });
                }
            }
        });
        
        if (inconsistentItems.length > 0) {
            // Create detailed error message
            let message = `<div style='max-height: 400px; overflow-y: auto;'>`;
            message += `<strong>Brand Discount Consistency Error!</strong><br><br>`;
            message += `The following items have discount percentages that don't match their brand's standard discount:<br><br>`;
            
            message += `<table style='width: 100%; border-collapse: collapse; font-size: 12px;'>`;
            message += `<tr style='background: #f8f9fa; font-weight: bold;'>`;
            message += `<td style='padding: 8px; border: 1px solid #ddd;'>Item Code</td>`;
            message += `<td style='padding: 8px; border: 1px solid #ddd;'>Brand</td>`;
            message += `<td style='padding: 8px; border: 1px solid #ddd;'>Expected Discount</td>`;
            message += `<td style='padding: 8px; border: 1px solid #ddd;'>Actual Discount</td>`;
            message += `<td style='padding: 8px; border: 1px solid #ddd;'>Difference</td>`;
            message += `</tr>`;
            
            inconsistentItems.forEach(item => {
                message += `<tr style='background: #f8d7da;'>`;
                message += `<td style='padding: 8px; border: 1px solid #ddd;'><strong>${item.item_code}</strong></td>`;
                message += `<td style='padding: 8px; border: 1px solid #ddd;'>${item.brand}</td>`;
                message += `<td style='padding: 8px; border: 1px solid #ddd; text-align: center;'>${safeFormat(item.expected_discount, 2)}%</td>`;
                message += `<td style='padding: 8px; border: 1px solid #ddd; text-align: center;'>${safeFormat(item.actual_discount, 2)}%</td>`;
                message += `<td style='padding: 8px; border: 1px solid #ddd; text-align: center; color: red;'>${safeFormat(item.difference, 2)}%</td>`;
                message += `</tr>`;
            });
            
            message += `</table></div><br>`;
            message += `<div style='background: #e7f3ff; padding: 10px; border-left: 4px solid #007bff; margin: 10px 0;'>`;
            message += `<strong>Why this matters:</strong><br>`;
            message += `When the brand's average discount equals the manual discount, it means no manual override was applied. `;
            message += `All items of that brand should have the same discount percentage as specified in the brand discount table.`;
            message += `</div>`;
            message += `<strong>Recommended Actions:</strong><br>`;
            message += `• <strong>Auto-Fix Items:</strong> Update all items to match their brand discount<br>`;
            message += `• <strong>Continue Anyway:</strong> Save with inconsistent discounts (not recommended)<br>`;
            message += `• <strong>Cancel:</strong> Go back to review and fix manually`;
            
            // Create dialog with options
            let d = new frappe.ui.Dialog({
                title: 'Brand Discount Consistency Validation',
                fields: [
                    {
                        fieldname: 'message_html',
                        fieldtype: 'HTML',
                        options: message
                    }
                ],
                primary_action_label: 'Auto-Fix Items',
                primary_action(values) {
                    // Auto-fix all inconsistent items
                    let fixedCount = 0;
                    
                    inconsistentItems.forEach(item => {
                        // Find the item in the form and update its discount
                        let formItem = frm.doc.items.find(i => i.item_code === item.item_code && i.brand === item.brand);
                        if (formItem) {
                            frappe.model.set_value(formItem.doctype, formItem.name, "discount_percentage", item.expected_discount);
                            fixedCount++;
                        }
                    });
                    
                    // Refresh the form
                    frm.refresh_field("items");
                    
                    frappe.show_alert({
                        message: `Fixed discount for ${fixedCount} items to match brand standards`,
                        indicator: 'green'
                    });
                    
                    d.hide();
                    
                    // Update brand averages after fixing
                    setTimeout(() => {
                        updateBrandAveragesOnly(frm);
                        resolve(); // Continue with save
                    }, 500);
                },
                secondary_action_label: 'Continue Anyway',
                secondary_action() {
                    frappe.show_alert({
                        message: 'Saving with inconsistent brand discounts',
                        indicator: 'orange'
                    });
                    d.hide();
                    resolve(); // Continue with save
                }
            });
            
            // Add cancel button
            d.set_secondary_action(() => {
                d.hide();
                reject(); // Cancel save
            });
            
            d.show();
            
        } else {
            // All items are consistent with their brand discounts
            resolve();
        }
    });
}



