            message += `<strong>Why this matters:</strong><br>`;
            message += `When the brand's average discount equals the manual discount, it means no manual override was applied. `;
            message += `All items of that brand should have the same discount percentage as specified in the brand discount table.`;
            message += `</div>`;
            message += `<strong>Recommended Actions:</strong><br>`;
            message += `• <strong>Auto-Fix Items:</strong> Update all items to match their brand discount<br>`;
            message += `• <strong>Continue Anyway:</strong> Save with inconsistent discounts (not recommended)<br>`;
            message += `• <strong>Cancel:</strong> Go back to review and fix manually`;
            
            // Create dialog with options
            let d = new frappe.ui.Dialog({
                title: 'Brand Discount Consistency Validation',
                fields: [
                    {
                        fieldname: 'message_html',
                        fieldtype: 'HTML',
                        options: message
                    }
                ],
                primary_action_label: 'Auto-Fix Items',
                primary_action(values) {
                    // Auto-fix all inconsistent items
                    let fixedCount = 0;
                    
                    inconsistentItems.forEach(item => {
                        // Find the item in the form and update its discount
                        let formItem = frm.doc.items.find(i => i.item_code === item.item_code && i.brand === item.brand);
                        if (formItem) {
                            frappe.model.set_value(formItem.doctype, formItem.name, "discount_percentage", item.expected_discount);
                            fixedCount++;
                        }
                    });
                    
                    // Refresh the form
                    frm.refresh_field("items");
                    
                    frappe.show_alert({
                        message: `Fixed discount for ${fixedCount} items to match brand standards`,
                        indicator: 'green'
                    });
                    
                    d.hide();
                    
                    // Update brand averages after fixing
                    setTimeout(() => {
                        updateBrandAveragesOnly(frm);
                        resolve(); // Continue with save
                    }, 500);
                },
                secondary_action_label: 'Continue Anyway',
                secondary_action() {
                    frappe.show_alert({
                        message: 'Saving with inconsistent brand discounts',
                        indicator: 'orange'
                    });
                    d.hide();
                    resolve(); // Continue with save
                }
            });
            
            // Add cancel button
            d.set_secondary_action(() => {
                d.hide();
                reject(); // Cancel save
            });
            
            d.show();
            
        } else {
            // All items are consistent with their brand discounts
            resolve();
        }
    });
}

// UPDATED: Enhanced before_save function with consistency validation
function enhancedBeforeSave(frm) {
    return new Promise(async (resolve, reject) => {
        try {
            cleanNaNValues(frm);
            
            // First check for unapplied brand discount changes
            if (hasUnappliedBrandDiscountChanges(frm)) {
                frappe.confirm(
                    "Your brand wise discount is still not applied to items. Please finalize and save brand wise discount to proceed.",
                    function() {
                        reject();
                        return false;
                    },
                    function() {
                        reject();
                        return false;
                    }
                );
                return;
            }
            
            // NEW: Validate brand discount and item consistency
            await validateBrandDiscountItemConsistency(frm);
            
            // Validate that brand discount totals match item totals
            await validateBrandDiscountTotals(frm);
            
            // If we reach here, everything is good
            clearManualItemDiscounts();
            resolve();
            
        } catch (error) {
            console.error('Validation error:', error);
            reject();
        }
    });
}


// FIXED: Modified updateBrandAveragesOnly function with corrected average calculation
function updateBrandAveragesOnly(frm) {
    let brandDiscountMap = {};
    let manualDiscountMap = {};
    
    // First, collect all current manual discounts
    (frm.doc.custom_dicount_table || []).forEach(row => {
        if (row.brand) {
            manualDiscountMap[row.brand] = {
                manual_discount: safeNumber(row.manual_discount),
                is_explicit_zero: explicitZeroDiscounts[row.brand] || false
            };
        }
    });

    // Calculate weighted average discount for each brand
    (frm.doc.items || []).forEach(row => {
        if (row.brand) {
            if (!brandDiscountMap[row.brand]) {
                brandDiscountMap[row.brand] = {
                    total_discount_amount: 0,
                    total_value: 0,
                    total_weighted_discount: 0
                };
            }
            
            const itemValue = safeNumber(row.price_list_rate) * safeNumber(row.qty);
            const discountPercentage = safeNumber(row.discount_percentage);
            const discountAmount = (itemValue * discountPercentage) / 100;
            
            brandDiscountMap[row.brand].total_discount_amount += discountAmount;
            brandDiscountMap[row.brand].total_value += itemValue;
            // Calculate weighted discount contribution
            brandDiscountMap[row.brand].total_weighted_discount += (itemValue * discountPercentage);
        }
    });
    
    // Calculate average discount percentage for each brand
    Object.keys(brandDiscountMap).forEach(brand => {
        if (brandDiscountMap[brand].total_value > 0) {
            // This is the weighted average discount percentage
            brandDiscountMap[brand].average_discount = 
                safeNumber(brandDiscountMap[brand].total_weighted_discount / brandDiscountMap[brand].total_value);
        } else {
            brandDiscountMap[brand].average_discount = 0;
        }
    });

    // Update the brand discount table
    (frm.doc.custom_dicount_table || []).forEach(row => {
        if (brandDiscountMap[row.brand]) {
            // Always update the weighted average (read-only field) - this shows the actual average
            row.custom_average_discount = safeFormat(brandDiscountMap[row.brand].average_discount);
            
            // Check if this brand has a manual discount set
            const hasManualDiscount = manualDiscountMap[row.brand] && 
                (manualDiscountMap[row.brand].manual_discount > 0 || manualDiscountMap[row.brand].is_explicit_zero);
            
            if (!hasManualDiscount) {
                // Only update if no manual discount is set
                row.applied_discount = safeFormat(brandDiscountMap[row.brand].average_discount);
                row.disc_ = safeFormat(brandDiscountMap[row.brand].average_discount);
                row.manual_discount = safeFormat(brandDiscountMap[row.brand].manual_discount);
            }
            
            // Always recalculate discount amount and total value based on actual averages
            row.discount_amount = safeFormat(brandDiscountMap[row.brand].total_discount_amount);
            row.total_value = safeFormat(brandDiscountMap[row.brand].total_value - brandDiscountMap[row.brand].total_discount_amount);
            row.value = safeFormat(brandDiscountMap[row.brand].total_value);
        }
    });

    cleanNaNValues(frm);
    frm.refresh_field('custom_dicount_table');
}

