frappe.ui.form.on('Quotation', {
    onload: function(frm) {
        const styleId = 'item-selector-wrap-style';

        function injectStyle() {
            if (document.getElementById(styleId)) return;

            const style = document.createElement('style');
            style.id = styleId;
            style.innerHTML = `
                .modal .link-select-row .ellipsis {
                    white-space: normal !important;
                    overflow: visible !important;
                    text-overflow: unset !important;
                    max-width: 100% !important;
                    display: block !important;
                    word-break: break-word !important;
                    line-height: 1.3em !important;
                }
                .modal .link-select-row .ellipsis span {
                    white-space: normal !important;
                    overflow: visible !important;
                    text-overflow: unset !important;
                    display: inline !important;
                    word-break: break-word !important;
                    line-height: 1.3em !important;
                }
            `;
            document.head.appendChild(style);
        }

        function applyWrapping() {
            $('.modal .link-select-row .ellipsis').each(function () {
                $(this).css({
                    'white-space': 'normal',
                    'overflow': 'visible',
                    'text-overflow': 'unset',
                    'max-width': '100%',
                    'display': 'block',
                    'word-break': 'break-word',
                    'line-height': '1.3em'
                });

                $(this).find('span').css({
                    'white-space': 'normal',
                    'overflow': 'visible',
                    'text-overflow': 'unset',
                    'display': 'inline',
                    'word-break': 'break-word',
                    'line-height': '1.3em'
                });
            });
        }

        function startAutoApply() {
            injectStyle();

            let repeatCount = 0;
            const interval = setInterval(() => {
                applyWrapping();
                repeatCount++;

                if (repeatCount > 20) {
                    clearInterval(interval);
                }
            }, 250);
        }

        // Run on modal open
        $(document).on('shown.bs.modal', function () {
            startAutoApply();
        });

        // Run on typing in modal input
        $(document).on('input', '.modal input[data-fieldname="txt"]', function () {
            startAutoApply();
        });
    }
});

