// Method 2: Override the new_doc function to pre-populate item_code
$(document).ready(function() {
    // Hook into frappe's new_doc function
    let original_new_doc = frappe.new_doc;

    frappe.new_doc = function(doctype, opts) {
        if (doctype === 'Item') {
            // Get next item code before opening the form
            frappe.call({
                method: 'frappe.client.get_list',
                args: {
                    doctype: 'Item',
                    fields: ['item_code'],
                    order_by: 'CAST(item_code AS UNSIGNED) desc',
                    limit_page_length: 1
                },
                callback: function(r) {
                    let next_code = "00001";

                    if (r.message && r.message.length > 0) {
                        let last_code = r.message[0].item_code;
                        if (!isNaN(last_code)) {
                            next_code = (parseInt(last_code) + 1).toString().padStart(5, '0');
                        }
                    }

                    // Set the item_code in opts or create opts if it doesn't exist
                    if (!opts) opts = {};
                    if (!opts.defaults) opts.defaults = {};
                    opts.defaults.item_code = next_code;

                    // Call the original new_doc function with pre-populated data
                    original_new_doc.call(this, doctype, opts);
                }
            });
        } else {
            // For other doctypes, call the original function
            original_new_doc.call(this, doctype, opts);
        }
    };
});

