frappe.ui.form.on('Payment Entry', {
  onload: function(frm) {
    // Reset the flag every time the form loads
    frm.__duplicate_checked = false;
  },

  validate: async function (frm) {
    if (frm.__duplicate_checked) return;

    const reference_no = frm.doc.reference_no;
    const paid_amount = frm.doc.paid_amount;

    if (!reference_no || !paid_amount) return;

    await new Promise((resolve, reject) => {
      frappe.call({
        method: "frappe.client.get_list",
        args: {
          doctype: "Payment Entry",
          filters: [
            ["name", "!=", frm.doc.name],
            ["reference_no", "=", reference_no],
            ["paid_amount", "=", paid_amount],
            ["docstatus", "<", 2]
          ],
          fields: ["name", "party"],
          limit: 1
        },
        callback: function (res) {
          if (res.message && res.message.length > 0) {
            const existing = res.message[0];
            const entry_id = existing.name;
            const party_name = existing.party;

            frappe.confirm(
              `🚫 A Payment Entry already exists with:<br>
               <b>Reference No</b>: <code>${reference_no}</code><br>
               <b>Paid Amount</b>: ₹${paid_amount}<br>
               <b>Existing Entry</b>: <a href="/app/payment-entry/${entry_id}" target="_blank">${entry_id}</a><br>
               <b>Party</b>: ${party_name}<br><br>
               <b>Do you still want to proceed?</b>`,
              () => {
                frm.__duplicate_checked = true;
                resolve();
              },
              () => {
                frappe.msgprint("Cancelled by user due to duplicate entry.");
                reject("User cancelled due to duplicate");
              }
            );
          } else {
            frm.__duplicate_checked = true;
            resolve();
          }
        }
      });
    });
  }
});

