    before_save: function(frm) {
        validate_item_prices(frm);
    },

    // Validate before submitting the document
    before_submit: function(frm) {
        validate_item_prices(frm);
    }
});

// Function to validate all item prices
function validate_item_prices(frm) {
    if (!frm.doc.items || frm.doc.items.length === 0) {
        frappe.throw(__('Please add at least one item to the quotation.'));
        return false;
    }

    let zero_price_items = [];

    frm.doc.items.forEach(function(item, index) {
        // Allow items with 100% discount (free items)
        if ((!item.rate || item.rate === 0) && item.discount_percentage !== 100) {
            zero_price_items.push({
                item_code: item.item_code || 'Item at row ' + (index + 1),
                row: index + 1
            });
        }
    });

    if (zero_price_items.length > 0) {
        let error_message = __('The following items have zero or no price set:') + '<br><br>';

        zero_price_items.forEach(function(item) {
            error_message += '• ' + item.item_code + ' (Row ' + item.row + ')<br>';
        });

        error_message += '<br>' + __('Please set a valid price for all items before saving.');

        frappe.throw({
            message: error_message,
            title: __('Invalid Item Prices'),
            indicator: 'red'
        });

        return false;
    }

    return true;
}

