// Brand Discount Validation Script
// This script validates that discount amounts are properly calculated when discount percentages are applied

frappe.ui.form.on("Quotation", {
    before_save: function(frm) {
        validate_brand_discount_amounts(frm);
    }
});

function validate_brand_discount_amounts(frm) {
    let validation_errors = [];
    let items_with_issues = [];

    // Check each item in the quotation
    (frm.doc.items || []).forEach(function(item, index) {
        let discount_percentage = parseFloat(item.discount_percentage) || 0;
        let discount_amount = parseFloat(item.discount_amount) || 0;
        let price_list_rate = parseFloat(item.price_list_rate) || 0;
        let qty = parseFloat(item.qty) || 0;

        // Only validate if discount percentage is greater than 0
        if (discount_percentage > 0) {
            // Calculate expected discount amount
            let expected_discount_amount = (price_list_rate * qty * discount_percentage) / 100;

            // Check if discount amount is 0 or significantly different from expected
            // Using a small tolerance for floating point comparison
            let tolerance = 0.01;
            let difference = Math.abs(discount_amount - expected_discount_amount);

            if (discount_amount === 0 || difference > tolerance) {
                items_with_issues.push({
                    item_code: item.item_code,
                    item_name: item.item_name,
                    brand: item.brand,
                    row_number: index + 1,
                    discount_percentage: discount_percentage,
                    current_discount_amount: discount_amount,
                    expected_discount_amount: expected_discount_amount,
                    price_list_rate: price_list_rate,
                    qty: qty
                });
            }
        }
    });

    // If there are validation errors, show detailed error message and prevent save
    if (items_with_issues.length > 0) {
        let error_message = "Brand discount is not properly applied for the following items:\n\n";

        items_with_issues.forEach(function(item) {
            error_message += `Row ${item.row_number}: ${item.item_code} (${item.item_name})\n`;
            error_message += `  Brand: ${item.brand || 'Not Set'}\n`;
            error_message += `  Discount %: ${item.discount_percentage}%\n`;
            error_message += `  Current Discount Amount: ${item.current_discount_amount}\n`;
            error_message += `  Expected Discount Amount: ${item.expected_discount_amount.toFixed(2)}\n`;
            error_message += `  Price List Rate: ${item.price_list_rate}, Qty: ${item.qty}\n\n`;
        });

        error_message += "Please click 'Update Brand Discounts' button to recalculate and apply the discounts properly.";

        // Show error dialog
        frappe.msgprint({
            title: __('Brand Discount Validation Error'),
            message: error_message,
            indicator: 'red'
        });

        // Prevent save
        frappe.validated = false;
        return false;
    }

    return true;
}

// Optional: Add a function to fix discount amounts automatically
function fix_discount_amounts(frm) {
    let items_fixed = 0;

    (frm.doc.items || []).forEach(function(item) {
        let discount_percentage = parseFloat(item.discount_percentage) || 0;
        let discount_amount = parseFloat(item.discount_amount) || 0;
        let price_list_rate = parseFloat(item.price_list_rate) || 0;
        let qty = parseFloat(item.qty) || 0;

        if (discount_percentage > 0 && discount_amount === 0) {
            // Calculate and set the correct discount amount
            let expected_discount_amount = (price_list_rate * qty * discount_percentage) / 100;

            // Set the discount amount
            frappe.model.set_value(item.doctype, item.name, 'discount_amount', expected_discount_amount);

            // Also recalculate the rate (amount after discount)
            let rate_after_discount = price_list_rate * (1 - discount_percentage / 100);
            frappe.model.set_value(item.doctype, item.name, 'rate', rate_after_discount);

            items_fixed++;
        }
    });

    if (items_fixed > 0) {
        frappe.show_alert({
            message: `Fixed discount amounts for ${items_fixed} item(s)`,
            indicator: 'green'
        }, 5);

        frm.refresh_field('items');
    }

    return items_fixed;
}

