var brandDiscounts = {};
var isBrandDiscountTriggered = false;
var manuallySetItemDiscounts = [];
var explicitZeroDiscounts = {};

// NEW: Track original brand discount values and manual changes
var originalBrandDiscounts = {};
var manualBrandDiscountChanges = {};
var brandDiscountsApplied = false;

// Utility function to safely convert values and prevent NaN
function safeNumber(value, defaultValue = 0) {
    if (value === null || value === undefined || isNaN(value) || !isFinite(value)) {
        return defaultValue;
    }
    return parseFloat(value) || defaultValue;
}

// Utility function to safely format numbers
function safeFormat(value, decimals = 2) {
    const num = safeNumber(value);
    return num.toFixed(decimals);
}

// Add function to track manual item discount changes
function trackManualItemDiscount(itemName, brand, oldDiscount, newDiscount) {
    // Remove existing entry for this item
    manuallySetItemDiscounts = manuallySetItemDiscounts.filter(item => item.name !== itemName);

    // Add new entry if discount was manually changed
    if (newDiscount !== oldDiscount) {
        manuallySetItemDiscounts.push({
            name: itemName,
            brand: brand,
            old_discount: oldDiscount,
            new_discount: newDiscount
        });
    }
}

// Add function to clear manual tracking
function clearManualItemDiscounts() {
    manuallySetItemDiscounts = [];
}

// NEW: Function to store original brand discount values
function storeOriginalBrandDiscounts(frm) {
    originalBrandDiscounts = {};
    (frm.doc.custom_dicount_table || []).forEach(row => {
        if (row.brand) {
            originalBrandDiscounts[row.brand] = safeNumber(row.manual_discount);
        }
    });
}

// NEW: Function to track manual brand discount changes
function trackManualBrandDiscountChange(brand, oldValue, newValue) {
    if (safeNumber(oldValue) !== safeNumber(newValue)) {
        manualBrandDiscountChanges[brand] = {
            original: safeNumber(oldValue),
            current: safeNumber(newValue)
        };
    } else {
        // Remove if values are same
        delete manualBrandDiscountChanges[brand];
    }
}

// NEW: Function to check if there are unapplied brand discount changes
function hasUnappliedBrandDiscountChanges(frm) {
    // Check if there are any manual changes that haven't been applied
    return Object.keys(manualBrandDiscountChanges).length > 0 && !brandDiscountsApplied;
}

// NEW: Function to clear brand discount tracking
function clearBrandDiscountTracking() {
    manualBrandDiscountChanges = {};
    brandDiscountsApplied = false;
}

// Add function to get items that would be overridden
function getItemsToOverride(frm) {
    let itemsToOverride = [];

    manuallySetItemDiscounts.forEach(manualItem => {
        // Find corresponding brand discount
        let brandDiscount = frm.doc.custom_dicount_table.find(row => row.brand === manualItem.brand);

        if (brandDiscount && safeNumber(brandDiscount.manual_discount) !== safeNumber(manualItem.new_discount)) {
            // Find the actual item in the form
            let item = frm.doc.items.find(i => i.name === manualItem.name);
            if (item) {
                itemsToOverride.push({
                    item_code: item.item_code,
                    brand: item.brand,
                    current_discount: manualItem.new_discount,
                    new_discount: brandDiscount.manual_discount
                });
            }
        }
    });

    return itemsToOverride;
}

// Fetch brand separately for each Pricing Rule
function getBrandFromPricingRule(pricingRuleName, discountPercentage, brandDiscounts) {
    frappe.call({
        method: "frappe.client.get",
        args: {
            doctype: "Pricing Rule",
            name: pricingRuleName
        },
        async: true,
        callback: function(response) {
            if (response.message && response.message.brands) {
                // Store discount percentage for the brand
                brandDiscounts[response.message.brands[0].brand] = safeNumber(discountPercentage);
            }
        }
    });
}

// Modified apply_brand_discounts function
function apply_brand_discounts(frm) {
    let brand_discounts = {};
    let exceeds_discount = false;

    (frm.doc.custom_dicount_table || []).forEach(row => {
        if (row.brand && row.manual_discount !== undefined) {
            const manualDiscount = safeNumber(row.manual_discount);
            const discDiscount = safeNumber(row.disc_);

            // Track if manual discount is explicitly set to zero
            if (manualDiscount === 0) {
                explicitZeroDiscounts[row.brand] = true;
            } else if (manualDiscount > 0) {
                // Remove from explicit zero tracking if set to positive value
                delete explicitZeroDiscounts[row.brand];
            }

            if (manualDiscount !== 0) {
                brand_discounts[row.brand] = manualDiscount;
            } else {
                // Use zero if explicitly set, otherwise use disc_
                brand_discounts[row.brand] = explicitZeroDiscounts[row.brand] ? 0 : discDiscount;
            }
        }
        if (safeNumber(row.manual_discount) > safeNumber(row.max_discount)) {
            exceeds_discount = true;
        }
    });

    (frm.doc.items || []).forEach(item => {
        if (item.brand && brand_discounts[item.brand] !== undefined) {
            let new_discount = brand_discounts[item.brand];
            frappe.model.set_value(item.doctype, item.name, "discount_percentage", new_discount);
        }
    });

    (frm.doc.custom_dicount_table || []).forEach(row => {
        if (row.brand && brand_discounts[row.brand] !== undefined) {
            const discountAmount = safeNumber((safeNumber(row.value) * safeNumber(row.custom_average_discount)) / 100);
            row.discount_amount = safeFormat(discountAmount);
            row.total_value = safeFormat(safeNumber(row.value) - discountAmount);
        }
    });

    cleanNaNValues(frm);
    frm.refresh_field("items");
    frm.refresh_field("custom_dicount_table");

    // NEW: Mark brand discounts as applied and clear tracking
    brandDiscountsApplied = true;
    clearBrandDiscountTracking();
    storeOriginalBrandDiscounts(frm);

    if (exceeds_discount) {
        if ("custom_requires_approval_for_discount" in frm.doc) {
            frm.set_value("custom_requires_approval_for_discount", 1);
        } else {
            console.error("Error: Field 'custom_requires_approval' not found in Quotation Doctype!");
        }

        if (frm.doc.custom_requires_approval_for_discount) {
            frm.refresh();
        }
    }
}

// UPDATED: Clean NaN values function
function cleanNaNValues(frm) {
    (frm.doc.custom_dicount_table || []).forEach(row => {
        row.value = safeFormat(row.value || 0);
        row.disc_ = safeFormat(row.disc_ || 0);
        row.custom_average_discount = safeFormat(row.custom_average_discount || 0);
        row.applied_discount = safeFormat(row.applied_discount || 0);
        row.manual_discount = safeFormat(row.manual_discount || 0);
        row.discount_amount = safeFormat(row.discount_amount || 0);
        row.total_value = safeFormat(row.total_value || 0);
        row.max_discount = safeFormat(row.max_discount || 0);
    });
}

// FIXED: Modified updateBrandAveragesOnly function with corrected average calculation
function updateBrandAveragesOnly(frm) {
    let brandDiscountMap = {};
    let manualDiscountMap = {};

    // First, collect all current manual discounts
    (frm.doc.custom_dicount_table || []).forEach(row => {
        if (row.brand) {
            manualDiscountMap[row.brand] = {
                manual_discount: safeNumber(row.manual_discount),
                is_explicit_zero: explicitZeroDiscounts[row.brand] || false
            };
        }
    });

    // Calculate weighted average discount for each brand
    (frm.doc.items || []).forEach(row => {
        if (row.brand) {
            if (!brandDiscountMap[row.brand]) {
                brandDiscountMap[row.brand] = {
                    total_discount_amount: 0,
                    total_value: 0,
                    total_weighted_discount: 0
                };
            }

            const itemValue = safeNumber(row.price_list_rate) * safeNumber(row.qty);
            const discountPercentage = safeNumber(row.discount_percentage);
            const discountAmount = (itemValue * discountPercentage) / 100;

            brandDiscountMap[row.brand].total_discount_amount += discountAmount;
            brandDiscountMap[row.brand].total_value += itemValue;
            // Calculate weighted discount contribution
            brandDiscountMap[row.brand].total_weighted_discount += (itemValue * discountPercentage);
        }
    });

    // Calculate average discount percentage for each brand
    Object.keys(brandDiscountMap).forEach(brand => {
        if (brandDiscountMap[brand].total_value > 0) {
            // This is the weighted average discount percentage
            brandDiscountMap[brand].average_discount = 
                safeNumber(brandDiscountMap[brand].total_weighted_discount / brandDiscountMap[brand].total_value);
        } else {
            brandDiscountMap[brand].average_discount = 0;
        }
    });

    // Update the brand discount table
    (frm.doc.custom_dicount_table || []).forEach(row => {
        if (brandDiscountMap[row.brand]) {
            // Always update the weighted average (read-only field) - this shows the actual average
            row.custom_average_discount = safeFormat(brandDiscountMap[row.brand].average_discount);

            // Check if this brand has a manual discount set
            const hasManualDiscount = manualDiscountMap[row.brand] && 
                (manualDiscountMap[row.brand].manual_discount > 0 || manualDiscountMap[row.brand].is_explicit_zero);

            if (!hasManualDiscount) {
                // Only update if no manual discount is set
                row.applied_discount = safeFormat(brandDiscountMap[row.brand].average_discount);
                row.disc_ = safeFormat(brandDiscountMap[row.brand].average_discount);
                row.manual_discount = safeFormat(brandDiscountMap[row.brand].average_discount);
            }

            // Always recalculate discount amount and total value based on actual averages
            row.discount_amount = safeFormat(brandDiscountMap[row.brand].total_discount_amount);
            row.total_value = safeFormat(brandDiscountMap[row.brand].total_value - brandDiscountMap[row.brand].total_discount_amount);
            row.value = safeFormat(brandDiscountMap[row.brand].total_value);
        }
    });

    cleanNaNValues(frm);
    frm.refresh_field('custom_dicount_table');
}

frappe.ui.form.on("Quotation", {

    custom_update_brand_discount: function(frm) {
        // Check if there are items that would be overridden
        let itemsToOverride = getItemsToOverride(frm);

        if (itemsToOverride.length > 0) {
            // Create message for popup
            let message = "The following items have manually set discounts that will be overridden:<br><br>";
            itemsToOverride.forEach(item => {
                message += `• ${item.item_code} (${item.brand}): ${item.current_discount}% → ${item.new_discount}%<br>`;
            });
            message += "<br>Do you want to continue?";

            frappe.confirm(
                message,
                function() {
                    // User clicked Yes - proceed with update
                    frm.trigger("update_brand_discounts");
                    apply_brand_discounts(frm);
                    clearManualItemDiscounts(); // Clear tracking after update
                },
                function() {
                    // User clicked No - do nothing
                    return;
                }
            );
        } else {
            // No conflicts - proceed normally
            frm.trigger("update_brand_discounts");
            apply_brand_discounts(frm);
            clearManualItemDiscounts(); // Clear tracking after update
        }
    },

    refresh: function(frm) {
        // Store original values when form refreshes
        storeOriginalBrandDiscounts(frm);

        // Add a button in the form header
        frm.add_custom_button(__('Update Brand Discounts'), function() {
            // Check if there are items that would be overridden
            let itemsToOverride = getItemsToOverride(frm);

            if (itemsToOverride.length > 0) {
                // Create message for popup
                let message = "The following items have manually set discounts that will be overridden:<br><br>";
                itemsToOverride.forEach(item => {
                    message += `• ${item.item_code} (${item.brand}): ${item.current_discount}% → ${item.new_discount}%<br>`;
                });
                message += "<br>Do you want to continue?";

                frappe.confirm(
                    message,
                    function() {
                        // User clicked Yes - proceed with update
                        frm.trigger("update_brand_discounts");
                        apply_brand_discounts(frm);
                        clearManualItemDiscounts(); // Clear tracking after update
                    },
                    function() {
                        // User clicked No - do nothing
                        return;
                    }
                );
            } else {
                // No conflicts - proceed normally
                frm.trigger("update_brand_discounts");
                apply_brand_discounts(frm);
                clearManualItemDiscounts(); // Clear tracking after update
            }
        }).addClass('btn-primary'); // Make it visually distinct
    },

    // UPDATED: Enhanced before_save validation to check for unapplied brand discount changes
    before_save: function(frm) {
        return new Promise((resolve, reject) => {
            cleanNaNValues(frm);

            // Check if there are unapplied brand discount changes
            if (hasUnappliedBrandDiscountChanges(frm)) {
                frappe.confirm(
                    "Your brand wise discount is still not applied to items. Please finalize and save brand wise discount to proceed.",
                    function() {
                        // User wants to continue without applying - reject save
                        reject();
                        return false;
                    },
                    function() {
                        // User canceled - reject save
                        reject();
                        return false;
                    }
                );
            } else {
                // No unapplied changes - proceed with save
                clearManualItemDiscounts();
                resolve();
            }
        });
    },

    onload: function(frm) {
        clearManualItemDiscounts();
        clearBrandDiscountTracking();
        storeOriginalBrandDiscounts(frm);

        if (!isBrandDiscountTriggered) {
            // Fetch all pricing rules and store discount percentages
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Pricing Rule",
                    fields: ["name", "discount_percentage"],
                    limit_page_length: 1000
                },
                async: false,
                callback: function(response) {
                    if (response.message) {
                        response.message.forEach(rule => {
                            getBrandFromPricingRule(rule.name, rule.discount_percentage, brandDiscounts);
                        });
                    }
                }
            });
        }
    },

    validate: function(frm) {
        // Clean NaN values before validation
        cleanNaNValues(frm);

        let exceeds_discount = false;

        // Check manual discounts in the custom discount table
        (frm.doc.custom_dicount_table || []).forEach(row => {
            let brand = row.brand;
            let manual_discount = safeNumber(row.manual_discount);

            if (brand && brandDiscounts[brand] !== undefined) {
                if (manual_discount > brandDiscounts[brand]) {
                    exceeds_discount = true;
                }
            }
        });

        if (exceeds_discount) {
            if ("custom_requires_approval_for_discount" in frm.doc) {
                frm.set_value("custom_requires_approval_for_discount", 1);
            } else {
                console.error("Error: Field 'custom_requires_approval' not found in Quotation Doctype!");
            }

            if (frm.doc.custom_requires_approval_for_discount) {
                frm.refresh();
            }
        }
    },

    // FIXED: Main update function with corrected weighted average calculation
    update_brand_discounts: function(frm) {
        console.log("1");

        if (!frm.doc.items || frm.doc.items.length === 0) {
            frm.clear_table("custom_dicount_table");
            frm.refresh_field("custom_dicount_table");
            console.log("2");
            return;
        }

        let brand_totals = {};
        let manual_discounts = {};

        // Store existing manual discounts from brand table
        if (frm.doc.custom_dicount_table) {
            frm.doc.custom_dicount_table.forEach(row => {
                manual_discounts[row.brand] = safeNumber(row.manual_discount);

                // Track explicit zero discounts
                if (safeNumber(row.manual_discount) === 0 && explicitZeroDiscounts[row.brand]) {
                    manual_discounts[row.brand] = 0;
                }
            });
        }

        // Calculate brand totals using CURRENT item discounts (preserve manual changes)
        frm.doc.items.forEach(item => {
            if (item.brand) {
                if (!brand_totals[item.brand]) {
                    brand_totals[item.brand] = {
                        value: 0,
                        total_discount_amount: 0,
                        total_weighted_discount: 0,
                        item_count: 0,
                        manual_discount: manual_discounts[item.brand] || 0
                    };
                }

                const itemValue = safeNumber(item.price_list_rate) * safeNumber(item.qty);
                const itemDiscount = safeNumber(item.discount_percentage);
                const discountAmount = (itemValue * itemDiscount) / 100;

                brand_totals[item.brand].value += itemValue;
                brand_totals[item.brand].total_discount_amount += discountAmount;
                // FIXED: Calculate weighted discount properly
                brand_totals[item.brand].total_weighted_discount += (itemValue * itemDiscount);
                brand_totals[item.brand].item_count += 1;
            }
        });

        console.log(brand_totals);

        frappe.call({
            method: "erpnext_mxt.custom_functions.brand_discount.get_brand_discounts",
            args: {
                brand_list: Object.keys(brand_totals)
            },
            callback: function(r) {
                if (r.message && Array.isArray(r.message) && r.message.length > 0) {
                    frm.clear_table("custom_dicount_table");
                    console.log("3");

                    r.message.forEach(rule => {
                        if (brand_totals[rule.brand]) {
                            brand_totals[rule.brand].max_discount_percentage = safeNumber(rule.discount_percentage);
                            brand_totals[rule.brand].default_discount_percentage = safeNumber(rule.custom_default_discount_percentage);

                            // FIXED: Calculate weighted average discount properly
                            brand_totals[rule.brand].weighted_average_discount = 
                                brand_totals[rule.brand].value > 0 ? 
                                safeNumber(brand_totals[rule.brand].total_weighted_discount / brand_totals[rule.brand].value) : 0;

                            // Use weighted average as the primary calculation
                            brand_totals[rule.brand].average_discount = brand_totals[rule.brand].weighted_average_discount;

                            // Check if this brand has explicit zero discount
                            if (explicitZeroDiscounts[rule.brand]) {
                                brand_totals[rule.brand].average_discount = 0;
                                brand_totals[rule.brand].manual_discount = 0;
                            } else {
                                // Use default discount if no items have discounts yet and no explicit zero
                                if (brand_totals[rule.brand].average_discount === 0 && brand_totals[rule.brand].manual_discount === 0) {
                                    brand_totals[rule.brand].average_discount = brand_totals[rule.brand].default_discount_percentage;

                                    // Apply default discount to items that don't have any discount
                                    frm.doc.items.forEach(item => {
                                        if (item.brand === rule.brand && safeNumber(item.discount_percentage) === 0) {
                                            frappe.model.set_value(item.doctype, item.name, 'discount_percentage', brand_totals[rule.brand].default_discount_percentage);
                                        }
                                    });
                                }
                            }

                            // Override with zero if explicitly set
                            if (explicitZeroDiscounts[rule.brand]) {
                                brand_totals[rule.brand].average_discount = 0;
                            }

                            brand_totals[rule.brand].discount_amount = safeNumber(
                                (brand_totals[rule.brand].value * brand_totals[rule.brand].weighted_average_discount) / 100
                            );
                        }
                    });

                    Object.keys(brand_totals).forEach(brand => {
                        let row = frm.add_child("custom_dicount_table");
                        console.log("8");
                        if (row) {
                            row.brand = brand;
                            row.value = safeFormat(brand_totals[brand].value);
                            row.disc_ = safeFormat(brand_totals[brand].average_discount);
                            row.discount_amount = safeFormat(brand_totals[brand].discount_amount);
                            row.total_value = safeFormat(brand_totals[brand].value - brand_totals[brand].discount_amount);
                            row.max_discount = safeFormat(brand_totals[brand].max_discount_percentage);
                            row.applied_discount = safeFormat(brand_totals[brand].average_discount);
                            // FIXED: Set custom_average_discount to show the actual weighted average
                            row.custom_average_discount = safeFormat(brand_totals[brand].weighted_average_discount);

                            // Handle manual_discount for explicit zeros
                            if (explicitZeroDiscounts[brand]) {
                                row.manual_discount = safeFormat(0);
                            } else {
                                // Set manual_discount to match disc_ when it's calculated from item averages
                                if (brand_totals[brand].manual_discount <= 0 && brand_totals[brand].average_discount > 0) {
                                    row.manual_discount = safeFormat(brand_totals[brand].average_discount);
                                } else {
                                    row.manual_discount = safeFormat(brand_totals[brand].manual_discount);
                                }
                            }

                            console.log(row);
                        }
                    });

                    frm.refresh_field("custom_dicount_table");
                    frm.refresh_field("items");

                    // NEW: Store original values after update
                    storeOriginalBrandDiscounts(frm);
                    clearBrandDiscountTracking();

                    console.log("Table Refreshed");
                } else {
                    console.log("Refresh");
                    frm.clear_table("custom_dicount_table");
                    frm.refresh_field("custom_dicount_table");
                    storeOriginalBrandDiscounts(frm);
                    clearBrandDiscountTracking();
                }
            }
        });

        frm.refresh();
    }
});

