// first, we'll extend the base ListView class described here:
// https://github.com/frappe/frappe/blob/e8c1a27a7a0c66ffad165bb2c6b3fa3d603228c4/frappe/public/js/frappe/list/list_view.js#L6
frappe.views.ListView = class ListView extends frappe.views.ListView {
    // in this first method override, we'll add additional parameters
    // and define an extended template for the listview row
    get_list_row_html_skeleton(left = "", right = "", details = "") {
        // check to make sure that we're viewing the right doctype.
        // (this code will load for the Item doctype, but it will stay in memory when viewing other lists)
        if (this.doctype === "Item") {
            if (details === null) { details = "" };
            return `
                <div class="list-row-container" tabindex="1">
                    <div class="level list-row">
                        <div class="level-left ellipsis">
                            ${left}
                        </div>
                        <div class="level-right text-muted ellipsis">
                            ${right}
                        </div>
                    </div>
                    <div class="level list-row details-row">
                        <div class="mobile-details">
                            ${details}
                        </div>
                    </div>
                </div>
            `;
        }
    }

    // in this second method override, we'll pass the extra variables from our doc object
    // over to our template generator
    get_list_row_html(doc) {
        // Create details content with brand and other item details
        const detailsContent = this.get_mobile_details(doc);

        return this.get_list_row_html_skeleton(
            this.get_left_html(doc),
            this.get_right_html(doc),
            detailsContent
        );
    }

    // New method to format the mobile details content
    get_mobile_details(doc) {
        if (this.doctype === "Item") {
            const details = [];

            // Add Brand if available
            if (doc.brand) {
                details.push(`<span class="detail-item"><strong>Brand:</strong> ${doc.brand}</span>`);
            }
            if (doc.custom_sku_code) {
                details.push(`<span class="detail-item"><strong>SKU Code:</strong> ${doc.custom_sku_code}</span>`);
            }

            return details.join('');
        }
        return '';
    }
}
