function clean_name(name) {
    // Remove everything related to (DON'T CALL), numbers, and similar patterns
    return name
        .replace(/\(?\s*DON'?T\s*CALL\s*\)?/gi, '')           // Remove (DON'T CALL)
        .replace(/\(?\s*DONT'? CALL\s*\)?/gi, '')             // Remove DONT CALL
        .replace(/\(?\s*DOT CALL\s*\)?/gi, '')                // Remove DOT CALL typo
        .replace(/\(?\s*CALL ONLY AFTER.*?\)?/gi, '')         // Remove instructions like "CALL ONLY AFTER 6PM"
        .replace(/\(?\s*CALL.*?\)?/gi, '')                    // Remove any "(CALL ...)"
        .replace(/\+?\d[\d\-\(\) ]{6,}/g, '')                 // Remove phone numbers
        .replace(/Duplicate of.*$/i, '')                      // Remove "Duplicate of ..." notes
        .replace(/\s+/g, ' ')                                 // Remove extra spaces
        .trim();
}

